/**
 * auraToolkit.ts — AURA-MCP (Versión Consolidada)
 * -------------------------------------------------------------
 * Toolkit oficial para la provisión de tools a:
 *
 *  ✔ Agentes LangChain
 *  ✔ AURA Pipeline Engine
 *  ✔ OrchestratorCore
 *  ✔ MCP Servers y SubAgentes
 *
 * Funcionalidades:
 *  - Expone tools locales del Core
 *  - Integra tools externas (n8n, Zapier, PowerAutomate…)
 *  - Carga dinámica de tools MCP remotas
 *  - Filtrado avanzado basado en:
 *       · allowedTools (AllowedTools del agente)
 *       · allowedScopes (Access Control)
 *       · AgentType (orchestrator / security / tool-only…)
 *
 * Alineado a:
 *  - agentSchemas.ts (2025 consolidated)
 *  - MCP LangChain Integration Layer
 *  - Prompt System Filtrados
 *  - AURA-MCP Orchestration Core
 */

import { Logger } from '../../src/lib/logger.js';
import { CoreTools } from '../../src/tools/coreTools.js';
import { MCPToolLoader } from '../engine/mcpToolLoader.js';
import { AgentDefinition } from '../../src/lib/agentFactory.js';

// Tipo estándar de tool para LangChain
export type LC_Tool = {
  name: string;
  description: string;
  func: (input: any) => Promise<any>;
};

// Cache para MCP tools remotas
let cachedMcpTools: LC_Tool[] = [];

// ==============================================================
// 1. TOOLS LOCALES DEL CORE — disponibles para todos los agentes
// ==============================================================

function localTools(): LC_Tool[] {
  return [
    {
      name: 'core.sql.query',
      description: 'Ejecuta queries SQL con control de acceso interno.',
      func: async (args) => CoreTools.sqlQuery(args),
    },
    {
      name: 'core.repo.get_prompt',
      description: 'Obtiene un systemPrompt o archivo desde el Repo AURA.',
      func: async (args) => CoreTools.repoGetPrompt(args),
    },
    {
      name: 'core.route_tool',
      description: 'Redirige una tool a un módulo MCP remoto.',
      func: async (args) => CoreTools.routeTool(args),
    },
    {
      name: 'core.agent.get',
      description: 'Obtiene metadata y configuración de un agente AURA.',
      func: async (args) => CoreTools.agentGet(args),
    },
  ];
}

// ==============================================================
// 2. TOOLS EXTERNAS DEL ECOSISTEMA — integraciones reales
// ==============================================================

function externalTools(): LC_Tool[] {
  return [
    {
      name: 'automation.n8n.run_workflow',
      description: 'Ejecución de workflows n8n desde AURA.',
      func: async (args) => CoreTools.automationN8nRunWorkflow(args),
    },
    {
      name: 'automation.power_automate.run',
      description: 'Ejecuta Flows de Power Automate.',
      func: async (args) => CoreTools.automationPowerAutomateRun(args),
    },
    {
      name: 'automation.zapier.trigger',
      description: 'Webhook Zapier Trigger.',
      func: async (args) => CoreTools.automationZapierTrigger(args),
    },
  ];
}

// ==============================================================
// 3. CARGA DE TOOLS MCP REMOTAS DINÁMICAS (SubAgentes / Servers)
// ==============================================================

async function loadMcpTools(): Promise<LC_Tool[]> {
  try {
    const tools = await MCPToolLoader.loadAllTools();

    cachedMcpTools = tools.map((t) => ({
      name: t.name,
      description: t.description ?? 'Tool remota MCP',
      func: async (args) => await t.call(args),
    }));

    Logger.info('[AURA_TOOLKIT] Tools MCP cargadas', {
      total: cachedMcpTools.length,
    });

    return cachedMcpTools;
  } catch (err: any) {
    Logger.error('[AURA_TOOLKIT] Error al cargar tools MCP', {
      error: err.message,
    });
    return [];
  }
}

// ==============================================================
// 4. FILTRADO POR SCOPES — ACCESS CONTROL
// ==============================================================

// ...
function filterToolsByScopes(tools: LC_Tool[], agent: AgentDefinition): LC_Tool[] {
  // Cast to any to access optional extended properties
  const scopes = (agent as any).allowedScopes;
  if (!scopes || scopes.length === 0) return tools;

  return tools.filter((t) =>
    scopes.some((scope: string) => t.name.startsWith(scope) || t.name.includes(scope))
  );
}

function filterByAllowedTools(tools: LC_Tool[], agent: AgentDefinition): LC_Tool[] {
  // Map 'tools' from AgentDefinition to logic
  const allowed = agent.tools || (agent as any).allowedTools;
  if (!allowed || allowed.length === 0) return tools;

  return tools.filter((t) => allowed.includes(t.name));
}

function filterByAgentType(tools: LC_Tool[], agent: AgentDefinition): LC_Tool[] {
  const type = agent.type as string; // Allow broader types
  switch (type) {
    case 'orchestrator':
      return tools;
    case 'security':
      return tools.filter((t) => !t.name.includes('sql'));
    case 'tool':
      const allowed = agent.tools || (agent as any).allowedTools || [];
      return tools.filter((t) => allowed.includes(t.name));
    default:
      return tools;
  }
}

// ==============================================================
// 7. MÉTODO PRINCIPAL — ENRUTADOR DE TOOLS PARA AGENTES
// ==============================================================

async function getToolsForAgent(agent: AgentDefinition): Promise<LC_Tool[]> {
  let tools: LC_Tool[] = [...localTools(), ...externalTools()];

  // Agregar MCP remotas
  const mcpTools = cachedMcpTools.length ? cachedMcpTools : await loadMcpTools();
  tools = [...tools, ...mcpTools];

  // Filtrar por allowedTools específicos
  tools = filterByAllowedTools(tools, agent);

  // Filtrar por scopes
  tools = filterToolsByScopes(tools, agent);

  // Filtrar por tipo de agente
  tools = filterByAgentType(tools, agent);

  Logger.info('[AURA_TOOLKIT] Tools asignadas a agente', {
    agent: agent.name,
    total: tools.length,
  });

  return tools;
}

// ==============================================================
// 8. EXPORT DEL TOOLKIT PARA PIPELINE ENGINE + LANGCHAIN
// ==============================================================

export const AURAToolkit = {
  async getTools(agent: AgentDefinition): Promise<LC_Tool[]> {
    return await getToolsForAgent(agent);
  },
};

// Registrar toolkit global
globalThis.AURA_TOOLKIT = AURAToolkit;

Logger.info('[AURA_TOOLKIT] Toolkit inicializado correctamente.');

/**
 * AgentEngine.ts — AURA-MCP
 * ====================================================================
 * Este archivo unifica:
 *
 *  ✔ AgentGenerator — Crear agentes dinámicos + escribir prompt file
 *  ✔ AgentFactory   — Construir agentes a partir de prompts
 *  ✔ AgentBuilder   — Construir agente LangChain (ReAct + Tools MCP)
 *  ✔ LangChainExecutor — Ejecutar agentes usando LLMs avanzados
 *
 * Cumple:
 *  - MCP Langchaing.pdf
 *  - Arquitectura AURA-MCP-Core
 *  - AURA Cognitive Layer
 *
 * Es el núcleo del sistema cognitivo distribuido de AURA.
 */

import fs from 'fs';
import path from 'path';

import { ChatOpenAI } from '@langchain/openai';
import { ChatPromptTemplate } from '@langchain/core/prompts';
type AgentExecutorAny = any;

import { Logger } from '../../src/lib/logger.js';
import { Config } from '../../src/lib/config.js';

import { AgentManager } from '../core/agentManager.js';
import { validateAgentDefinition, validatePromptHeader } from '../adapters/agentSchemas.js';

// =========================================================
// 1. AGENT GENERATOR — Crear agentes dinámicos
// =========================================================

export class AgentGenerator {
  static basePath = 'src/repository/prompts';

  static async createAgent(args: {
    name: string;
    role: string;
    tools?: string[];
    description?: string;
    systemPrompt?: string;
  }) {
    const { name, role, tools = [], description = '', systemPrompt = '' } = args;

    // Validación estructural previa
    const validated = validateAgentDefinition({
      id: name.toLowerCase().replace(/\s+/g, '-'),
      name,
      role: role as any,
      type: 'analysis',
      description,
      systemPrompt,
      capabilities: [],
      langchain: 'react',
      allowedTools: tools,
      allowedScopes: [],
      memory: {},
      temperature: 0.2,
    });

    const content = `# NAME: ${validated.name}
# ROLE: ${validated.role}
# TOOLS: ${validated.allowedTools.join(',')}

${validated.systemPrompt || 'Agente generado dinámicamente por AURA-MCP.'}
`;

    const filePath = path.join(AgentGenerator.basePath, `agent_${name}.txt`);
    fs.writeFileSync(filePath, content, 'utf8');

    AgentManager.register(validated);

    Logger.info('[AgentGenerator] Agente creado correctamente', {
      name,
      role,
    });

    return { ok: true, agent: validated };
  }
}

// =========================================================
// 2. AGENT FACTORY — Carga agentes desde archivo prompt
// =========================================================

export class AgentFactory {
  static filePath(id: string) {
    return path.join(process.cwd(), 'src/repository/prompts', `${id}.txt`);
  }

  static async createFromPrompt(agentId: string) {
    const fullPath = this.filePath(agentId);

    if (!fs.existsSync(fullPath)) {
      throw new Error(`Archivo prompt no encontrado: ${fullPath}`);
    }

    const raw = fs.readFileSync(fullPath, 'utf8');

    const NAME = raw.match(/#\s*NAME:\s*(.*)/)?.[1]?.trim();
    const ROLE = raw.match(/#\s*ROLE:\s*(.*)/)?.[1]?.trim();
    const TOOLS_LINE = raw.match(/#\s*TOOLS:\s*(.*)/)?.[1]?.trim() ?? '';

    if (!NAME || !ROLE) {
      throw new Error(`Header inválido en ${fullPath}`);
    }

    const _header = validatePromptHeader({
      NAME,
      ROLE,
      TOOLS: TOOLS_LINE.split(',')
        .map((t) => t.trim())
        .filter(Boolean),
    });

    const systemPrompt = raw
      .split('\n')
      .filter((l) => !l.trim().startsWith('#'))
      .join('\n')
      .trim();

    Logger.info('[AgentFactory] Construyendo agente desde prompt', {
      agentId,
    });

    return AgentBuilder.buildAgent(agentId, systemPrompt);
  }
}

// =========================================================
// 3. AGENT BUILDER — Construye agente LangChain + Tools MCP
// =========================================================

declare global {
  /* eslint-disable no-var */
  var AURA_TOOLKIT:
    | {
        getTools: (agent: any) => Promise<any[]>;
      }
    | undefined;
}

export class AgentBuilder {
  static async buildAgent(agentName: string, systemPrompt: string) {
    const meta = AgentManager.get(agentName);
    if (!meta) throw new Error(`Agente no encontrado: ${agentName}`);

    Logger.info('[AgentBuilder] Construyendo agente AURA', { agentName });

    // -------------------------------
    // 1. LLM Principal
    // -------------------------------
    const llm = new ChatOpenAI({
      modelName: Config.defaultLLM || process.env.AURA_MODEL || 'gpt-4.1',
      temperature: (meta as any).temperature ?? 0.2,
      streaming: true,
      apiKey: Config.openaiKey,
      callbacks: [],
    });

    // -------------------------------
    // 2. Tools (locales + MCP tools)
    // -------------------------------
    let tools: any[] = [];
    try {
      if (global.AURA_TOOLKIT) {
        tools = await global.AURA_TOOLKIT.getTools(meta);
      }
    } catch (err: any) {
      Logger.warn('[AgentBuilder] Error obteniendo tools', {
        agentName,
        error: err.message,
      });
    }

    Logger.info('[AgentBuilder] Tools cargadas', {
      agentName,
      totalTools: tools.length,
    });

    // -------------------------------
    // 3. Memoria conversacional LangChain
    // -------------------------------
    const memory = undefined;

    // -------------------------------
    // 4. Crear agente LangChain + tools
    // -------------------------------
    const { AgentExecutor, createToolCallingAgent } = await import('langchain/agents');
    const lcAgent = await createToolCallingAgent({
      llm,
      tools,
      prompt: ChatPromptTemplate.fromTemplate(systemPrompt),
    });

    // -------------------------------
    // 5. Crear executor
    // -------------------------------
    const executor = (AgentExecutor as any).fromAgentAndTools({
      agent: lcAgent,
      tools,
      memory,
      verbose: true,
    });

    return new LangChainExecutor(executor);
  }
}

// =========================================================
// 4. LANGCHAIN EXECUTOR — Ejecuta agentes construidos
// =========================================================

export class LangChainExecutor {
  private executor: AgentExecutorAny;

  constructor(executor: AgentExecutorAny) {
    this.executor = executor;
  }

  async run(input: string, context: any = {}) {
    Logger.info('[LangChainExecutor] Invocando agente', {
      preview: input.slice(0, 200),
    });

    const result = await this.executor.invoke({
      input,
      context,
    });

    return (result as any).output ?? result;
  }

  static async runAgent(agentName: string, input: string, context: any = {}) {
    const agent = AgentManager.get(agentName);
    if (!agent) {
      throw new Error(`Agente no encontrado: ${agentName}`);
    }

    const executor = await AgentFactory.createFromPrompt(agentName);
    return executor.run(input, context);
  }
}

/**
 * document.tool.ts — AURA-MCP
 * ================================================================================
 * Tool interno: document_agent
 *
 * Responsabilidades:
 *  - Recibir documentos (ruta local o base64) + metadata
 *  - Extraer texto plano (page-wise opcional)
 *  - Guardar metadata + contenido + embedding en Supabase (via VectorEngine)
 *
 * Usa:
 *  - VectorEngine (integration/vectorEngine.ts)
 *  - SupabaseConnector si quieres guardar metadata adicional
 *
 * Se asume que el procesamiento de PDF/archivos (OCR, etc.) lo hace
 * un adaptador global: globalThis.AURA_DOC_PARSER
 */

import { z } from 'zod';
import { Logger } from '../../src/lib/logger.js';
import VectorEngine from '../../integration/vectorEngine.js';
import SupabaseConnector from '../../integration/supabaseConnector.js';

export interface MCPTool {
  name: string;
  description: string;
  inputSchema: z.ZodTypeAny;
  outputSchema: z.ZodTypeAny;
  execute(input: any, context?: any): Promise<any>;
}

// ============================================================================
// 1. SCHEMAS
// ============================================================================

const DocumentActionEnum = z.enum(['parse', 'ingest', 'parse_and_ingest']);

const DocumentInputSchema = z.object({
  action: DocumentActionEnum,

  // Ruta local o URL accesible desde backend; o buffer base64
  source: z.object({
    type: z.enum(['path', 'url', 'base64']),
    value: z.string(),
  }),

  // Metadata asociada al documento
  metadata: z
    .object({
      id: z.string().optional(),
      name: z.string().optional(),
      category: z.string().optional(),
      tags: z.array(z.string()).optional(),
      clientId: z.string().optional(),
      contextId: z.string().optional(),
    })
    .optional(),

  // Opcional: cortar por páginas
  pageWise: z.boolean().default(false),
});

const ParsedPageSchema = z.object({
  page: z.number(),
  text: z.string(),
});

const DocumentOutputSchema = z.object({
  ok: z.boolean(),
  action: DocumentActionEnum,
  pages: z.array(ParsedPageSchema).optional(),
  // ids creados en supabase / vector store
  ingestedIds: z.array(z.string()).optional(),
  error: z.string().optional(),
});

// ============================================================================
// 2. IMPLEMENTACIÓN
// ============================================================================

async function parseDocument(
  source: { type: 'path' | 'url' | 'base64'; value: string },
  pageWise: boolean
): Promise<{ pages: { page: number; text: string }[] }> {
  const adapter = (globalThis as any).AURA_DOC_PARSER;

  if (!adapter) {
    throw new Error('Adaptador de documentos (AURA_DOC_PARSER) no configurado.');
  }

  const result = await adapter.parse(source, { pageWise });

  if (!result || !Array.isArray(result.pages)) {
    throw new Error('AURA_DOC_PARSER no devolvió páginas válidas.');
  }

  return { pages: result.pages };
}

async function ingestDocumentPages(
  pages: { page: number; text: string }[],
  metadata: Record<string, any> | undefined
): Promise<string[]> {
  const ids: string[] = [];

  for (const p of pages) {
    const baseMeta = {
      ...metadata,
      page: p.page,
    };

    // 1) Insertar en vector store
    const embedding = await VectorEngine.embedText(p.text);

    const client = SupabaseConnector.getClient();
    const cfg = (VectorEngine as any).config || {
      table: 'documents_embeddings',
      textColumn: 'content',
      embedColumn: 'embedding',
      metadataColumn: 'metadata',
    };

    const row: any = {
      [cfg.textColumn]: p.text,
      [cfg.embedColumn]: embedding,
      ...(cfg.metadataColumn ? { [cfg.metadataColumn]: baseMeta } : {}),
    };

    const { data, error } = await client.from(cfg.table).insert(row).select('id');

    if (error) {
      Logger.error('[document_agent] Error insertando página en vector store', {
        error: error.message,
      });
      continue;
    }

    const newId = data?.[0]?.id;
    if (newId) ids.push(String(newId));
  }

  return ids;
}

async function executeDocumentTool(input: unknown, _context: any = {}): Promise<any> {
  const parsed = DocumentInputSchema.parse(input);
  const { action, source, metadata, pageWise } = parsed;

  try {
    // 1) PARSE
    const { pages } = await parseDocument(source, pageWise || action !== 'ingest');

    if (action === 'parse') {
      return {
        ok: true,
        action,
        pages,
      };
    }

    // 2) INGEST
    const ingestedIds = await ingestDocumentPages(pages, metadata || {});

    return {
      ok: true,
      action,
      pages: action === 'parse_and_ingest' ? pages : undefined,
      ingestedIds,
    };
  } catch (err: any) {
    Logger.error('[document_agent] Error procesando documento', {
      action,
      error: err.message,
    });
    return {
      ok: false,
      action,
      error: err.message,
    };
  }
}

// ============================================================================
// 3. TOOL EXPORT
// ============================================================================

export const DocumentTool: MCPTool = {
  name: 'document_agent',
  description:
    'Tool interno para parsear documentos (PDF, etc.) y opcionalmente ingerirlos en el vector store para RAG.',
  inputSchema: DocumentInputSchema,
  outputSchema: DocumentOutputSchema,
  execute: executeDocumentTool,
};

export default DocumentTool;

/**
 * supabase.tool.ts — AURA-MCP
 * ================================================================================
 * Tool interno: supabase_agent
 *
 * Responsabilidades:
 *  - Ejecutar operaciones CRUD simples contra Supabase
 *  - Estar RLS-aware (se espera contexto de usuario apropiado)
 *
 * Usa:
 *  - SupabaseConnector (integration/supabaseConnector.ts)
 */

import { z } from 'zod';
import { Logger } from '../../src/lib/logger.js';
import SupabaseConnector from '../../integration/supabaseConnector.js';

export interface MCPTool {
  name: string;
  description: string;
  inputSchema: z.ZodTypeAny;
  outputSchema: z.ZodTypeAny;
  execute(input: any, context?: any): Promise<any>;
}

// ============================================================================
// 1. SCHEMAS
// ============================================================================

const SupabaseActionEnum = z.enum(['select', 'insert', 'update', 'delete']);

const SupabaseInputSchema = z.object({
  action: SupabaseActionEnum,
  table: z.string(),
  // where simple eq filters
  filters: z.record(z.any()).optional(),
  // payload para insert/update
  data: z.record(z.any()).optional(),
  // limit para select
  limit: z.number().optional(),
});

const SupabaseOutputSchema = z.object({
  ok: z.boolean(),
  action: SupabaseActionEnum,
  table: z.string(),
  data: z.any().optional(),
  error: z.string().optional(),
});

// ============================================================================
// 2. IMPLEMENTACIÓN
// ============================================================================

async function executeSupabaseTool(input: unknown, _context: any = {}): Promise<any> {
  const parsed = SupabaseInputSchema.parse(input);
  const client = SupabaseConnector.getClient();

  try {
    if (parsed.action === 'select') {
      let query = client.from(parsed.table).select('*');

      if (parsed.filters) {
        for (const k of Object.keys(parsed.filters)) {
          query = query.eq(k, parsed.filters[k]);
        }
      }

      if (parsed.limit) {
        query = query.limit(parsed.limit);
      }

      const { data, error } = await query;
      if (error) {
        Logger.error('[supabase_agent] Error SELECT', {
          table: parsed.table,
          error: error.message,
        });
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: error.message,
        };
      }

      return {
        ok: true,
        action: parsed.action,
        table: parsed.table,
        data,
      };
    }

    if (parsed.action === 'insert') {
      if (!parsed.data) {
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: "Falta 'data' para acción insert.",
        };
      }

      const { data, error } = await client.from(parsed.table).insert(parsed.data).select('*');

      if (error) {
        Logger.error('[supabase_agent] Error INSERT', {
          table: parsed.table,
          error: error.message,
        });
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: error.message,
        };
      }

      return {
        ok: true,
        action: parsed.action,
        table: parsed.table,
        data,
      };
    }

    if (parsed.action === 'update') {
      if (!parsed.data) {
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: "Falta 'data' para acción update.",
        };
      }

      let query = client.from(parsed.table).update(parsed.data);

      if (parsed.filters) {
        for (const k of Object.keys(parsed.filters)) {
          query = query.eq(k, parsed.filters[k]);
        }
      }

      const { data, error } = await query.select('*');

      if (error) {
        Logger.error('[supabase_agent] Error UPDATE', {
          table: parsed.table,
          error: error.message,
        });
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: error.message,
        };
      }

      return {
        ok: true,
        action: parsed.action,
        table: parsed.table,
        data,
      };
    }

    if (parsed.action === 'delete') {
      let query = client.from(parsed.table).delete();

      if (parsed.filters) {
        for (const k of Object.keys(parsed.filters)) {
          query = query.eq(k, parsed.filters[k]);
        }
      }

      const { data, error } = await query.select('*');
      if (error) {
        Logger.error('[supabase_agent] Error DELETE', {
          table: parsed.table,
          error: error.message,
        });
        return {
          ok: false,
          action: parsed.action,
          table: parsed.table,
          error: error.message,
        };
      }

      return {
        ok: true,
        action: parsed.action,
        table: parsed.table,
        data,
      };
    }

    return {
      ok: false,
      action: parsed.action,
      table: parsed.table,
      error: 'Acción no soportada.',
    };
  } catch (err: any) {
    Logger.error('[supabase_agent] Excepción general', {
      table: parsed.table,
      error: err.message,
    });
    return {
      ok: false,
      action: parsed.action,
      table: parsed.table,
      error: err.message,
    };
  }
}

// ============================================================================
// 3. TOOL EXPORT
// ============================================================================

export const SupabaseTool: MCPTool = {
  name: 'supabase_agent',
  description:
    'Tool interno para ejecutar operaciones CRUD simples sobre Supabase usando SupabaseConnector.',
  inputSchema: SupabaseInputSchema,
  outputSchema: SupabaseOutputSchema,
  execute: executeSupabaseTool,
};

export default SupabaseTool;

/**
 * AgentPromptInjector.ts — AURA-MCP (Enterprise 2025)
 * ================================================================================
 * Inyector de prompts para agentes AURA.
 *
 * Combina:
 *   - PromptSystemFiltered (filosofía global / meta-system prompt)
 *   - PromptTemplateRegistry (plantillas por agente/rol/etapa)
 *   - PromptPolicyEngine (políticas, filtros, temperatura)
 *
 * Objetivo:
 *   ✔ Construir el systemPrompt final de cada agente
 *   ✔ Inyectar contexto global + específico
 *   ✔ Ajustar temperatura según intención y rol
 *   ✔ Mantener trazabilidad de qué plantillas/políticas se aplicaron
 */

import { Logger } from '../src/lib/logger.js';
import { AgentManager } from './agentManager.js';

import { PromptTemplateRegistry, RenderResult } from './PromptTemplateRegistry.js';

import { PromptPolicyEngine } from './PromptPolicyEngine.js';
import { PromptSystemFiltered } from './PromptSystemFiltered.js';

import type { AgentDefinition } from './agentRegistry.js';
import type { PromptTemplateScope } from './PromptTemplateRegistry.js';

// ============================================================================
// 1. Tipos
// ============================================================================

export interface AgentPromptBuildOptions {
  /**
   * Datos adicionales para rellenar plantillas:
   *   - empresa, proyecto, objetivo, contexto, etc.
   */
  data?: Record<string, any>;

  /**
   * Si true, se loguea el detalle de plantillas/políticas aplicadas.
   */
  debug?: boolean;
}

export interface AgentPromptBuildResult {
  agentName: string;
  finalSystemPrompt: string;
  effectiveTemperature: number;
  appliedTemplates: {
    system?: string;
    memory?: string;
    context?: string;
  };
  appliedPolicies: string[];
}

// ============================================================================
// 2. Utilidades internas
// ============================================================================

function buildScopeForAgent(
  agent: AgentDefinition,
  stage: 'system' | 'memory' | 'context'
): PromptTemplateScope {
  return {
    agent: agent.name,
    role: agent.role as string,
    stage,
  };
}

// ============================================================================
// 3. Núcleo: AgentPromptInjector
// ============================================================================

class AgentPromptInjectorCore {
  /**
   * Construye el systemPrompt final para un agente específico.
   *
   * Pasos:
   *  1. Cargar meta-system prompt global (PromptSystemFiltered)
   *  2. Intentar usar plantilla de sistema (TemplateRegistry, stage=system)
   *  3. Plantilla de memoria y contexto (stage=memory/context)
   *  4. Combinar en un único system prompt estructurado
   *  5. Pasar por PromptPolicyEngine (sanitización + temperatura)
   */
  buildForAgent(
    agent: AgentDefinition,
    options: AgentPromptBuildOptions = {}
  ): AgentPromptBuildResult {
    const data = options.data || {};
    const debug = options.debug ?? false;

    const appliedTemplates: AgentPromptBuildResult['appliedTemplates'] = {};
    const appliedPolicies: string[] = [];

    // ------------------------------------------------------------------------
    // 1. Meta-system prompt global (filosofía AURA)
    // ------------------------------------------------------------------------
    const globalSystem = PromptSystemFiltered.getSystemPrompt();

    // ------------------------------------------------------------------------
    // 2. Plantilla SYSTEM por agente (si existe)
    // ------------------------------------------------------------------------
    let systemBlock = agent.systemPrompt || '';
    let systemTemplateId: string | undefined;

    try {
      const scope = buildScopeForAgent(agent, 'system');
      const systemTemplate = PromptTemplateRegistry.resolve(agent.name, scope);

      if (systemTemplate) {
        const rendered: RenderResult = PromptTemplateRegistry.render(
          systemTemplate.id,
          data,
          scope,
          { applyPolicies: false }
        );

        systemBlock = rendered.prompt;
        systemTemplateId = systemTemplate.id;
        appliedTemplates.system = systemTemplate.id;
      }
    } catch (err: any) {
      Logger.warn('[AgentPromptInjector] No se pudo renderizar template SYSTEM', {
        agent: agent.name,
        error: err.message,
      });
    }

    // Si no hay template y no hay systemPrompt definido, usar mínimo por defecto
    if (!systemBlock.trim()) {
      systemBlock = `Eres el agente ${agent.name} con rol ${agent.role}.`;
    }

    // ------------------------------------------------------------------------
    // 3. Plantilla MEMORY por agente (opcional)
    // ------------------------------------------------------------------------
    let memoryBlock = '';
    let memoryTemplateId: string | undefined;

    try {
      const scope = buildScopeForAgent(agent, 'memory');
      const memTemplate = PromptTemplateRegistry.resolve(agent.name + '_memory', scope);

      if (memTemplate) {
        const rendered: RenderResult = PromptTemplateRegistry.render(
          memTemplate.id,
          { ...data, memory: agent.memory || {} },
          scope,
          { applyPolicies: false }
        );

        memoryBlock = rendered.prompt;
        memoryTemplateId = memTemplate.id;
        appliedTemplates.memory = memTemplate.id;
      }
    } catch (err: any) {
      Logger.warn('[AgentPromptInjector] No se pudo renderizar template MEMORY', {
        agent: agent.name,
        error: err.message,
      });
    }

    // ------------------------------------------------------------------------
    // 4. Plantilla CONTEXT por agente (opcional)
    // ------------------------------------------------------------------------
    let contextBlock = '';
    let contextTemplateId: string | undefined;

    try {
      const scope = buildScopeForAgent(agent, 'context');
      const ctxTemplate = PromptTemplateRegistry.resolve(agent.name + '_context', scope);

      if (ctxTemplate) {
        const rendered: RenderResult = PromptTemplateRegistry.render(ctxTemplate.id, data, scope, {
          applyPolicies: false,
        });

        contextBlock = rendered.prompt;
        contextTemplateId = ctxTemplate.id;
        appliedTemplates.context = ctxTemplate.id;
      }
    } catch (err: any) {
      Logger.warn('[AgentPromptInjector] No se pudo renderizar template CONTEXT', {
        agent: agent.name,
        error: err.message,
      });
    }

    // ------------------------------------------------------------------------
    // 5. Ensamblaje del SYSTEM PROMPT FINAL
    // ------------------------------------------------------------------------
    const rawSystemPrompt = `
[AURA_GLOBAL_SYSTEM]
${globalSystem}

[AGENT_SYSTEM]
${systemBlock}

${memoryBlock ? `[AGENT_MEMORY]\n${memoryBlock}\n` : ''}

${contextBlock ? `[AGENT_CONTEXT]\n${contextBlock}\n` : ''}

[INSTRUCCIONES_FINALES]
- Sigue las políticas avanzadas de PromptPolicyEngine.
- Respeta siempre las reglas MUST/NEVER definidas en el sistema.
- Usa herramientas solo cuando agreguen valor real.
- Explica brevemente tus decisiones, sin mostrar tu razonamiento interno completo.
    `.trim();

    // ------------------------------------------------------------------------
    // 6. Pasar por PromptPolicyEngine
    // ------------------------------------------------------------------------
    const baseTemp = typeof agent.temperature === 'number' ? agent.temperature : 0.2;

    const policyResult = PromptPolicyEngine.apply(rawSystemPrompt, {
      agentRole: agent.role as string,
      baseTemperature: baseTemp,
      debug,
    });

    appliedPolicies.push(...policyResult.appliedPolicies);

    const finalSystemPrompt = policyResult.sanitizedPrompt;
    const effectiveTemperature = policyResult.modifiedTemperature ?? baseTemp;

    if (debug) {
      Logger.info('[AgentPromptInjector] Prompt final construido', {
        agent: agent.name,
        effectiveTemperature,
        appliedTemplates,
        appliedPolicies,
      });
    }

    return {
      agentName: agent.name,
      finalSystemPrompt,
      effectiveTemperature,
      appliedTemplates,
      appliedPolicies,
    };
  }

  /**
   * Inyecta el systemPrompt final en el agente y lo vuelve a registrar
   * en el AgentManager.
   */
  injectIntoAgent(
    agentName: string,
    options: AgentPromptBuildOptions = {}
  ): AgentDefinition | null {
    const existing = AgentManager.get(agentName) as AgentDefinition | undefined;

    if (!existing) {
      Logger.error('[AgentPromptInjector] Agente no encontrado', { agentName });
      return null;
    }

    const build = this.buildForAgent(existing, options);

    const updated: AgentDefinition = {
      ...existing,
      systemPrompt: build.finalSystemPrompt,
      temperature: build.effectiveTemperature,
    };

    AgentManager.register(updated);

    Logger.info('[AgentPromptInjector] SystemPrompt inyectado al agente', {
      agentName,
      effectiveTemperature: build.effectiveTemperature,
    });

    return updated;
  }

  /**
   * Inyecta prompts en TODOS los agentes registrados (si AgentManager.list existe).
   * Útil para fase de bootstrap.
   */
  injectForAllRegisteredAgents(options: AgentPromptBuildOptions = {}) {
    const listFn = (AgentManager as any).list;

    if (typeof listFn !== 'function') {
      Logger.warn(
        '[AgentPromptInjector] AgentManager.list no está disponible; no se puede hacer inyección masiva.'
      );
      return;
    }

    const agents: AgentDefinition[] = listFn();
    agents.forEach((a) => {
      this.injectIntoAgent(a.name, options);
    });

    Logger.info('[AgentPromptInjector] Inyección masiva completada', {
      total: agents.length,
    });
  }
}

// ============================================================================
// Export singleton
// ============================================================================

export const AgentPromptInjector = new AgentPromptInjectorCore();
export default AgentPromptInjector;

/**
 * GraphRAGBuilder.ts — AURA-MCP (Enterprise 2025)
 * ================================================================================
 * Construcción automática de grafos semánticos usando:
 *
 *   ✔ Nodos: entidades, conceptos, temas, chunks, documentos
 *   ✔ Aristas: relaciones semánticas, co-ocurrencias, dependencia lógica
 *   ✔ Integración con Graphiti Server (AURA_GRAPHITI)
 *   ✔ Integración opcional con VectorEngine + embeddings
 *   ✔ Extracción automática de entidades (NER)
 *   ✔ Linkeo multinivel (document → chunk → entidad → concepto)
 *
 * Alineado con:
 *    - RAG con Grafos (LightRAG, GraphRAG, RAG-Anything)
 *    - MCP + Graphiti Server
 *    - AURA-MCP Orchestrator (multihop reasoning)
 */

import { Logger } from '../lib/logger.js';
import VectorEngine from '../integration/vectorEngine.js';
import SupabaseConnector from '../integration/supabaseConnector.js';

const GRAPHITI = (globalThis as any).AURA_GRAPHITI || null;

// ============================================================================
// 1. Tipos internos
// ============================================================================

export interface GraphNode {
  id?: string;
  type: 'document' | 'chunk' | 'entity' | 'concept' | 'topic';
  label: string;
  metadata?: Record<string, any>;
  embedding?: number[];
}

export interface GraphEdge {
  source: string;
  target: string;
  relation: string;
  weight?: number;
  metadata?: Record<string, any>;
}

export interface GraphBuildResult {
  nodes: GraphNode[];
  edges: GraphEdge[];
  summary: string;
}

// ============================================================================
// 2. Utilidades internas
// ============================================================================

function extractEntities(text: string): string[] {
  /**
   * Mini-NER basado en heurísticas simples.
   * Puedes reemplazarlo por un modelo real via AURA_MODEL.invoke()
   */
  const entities = new Set<string>();

  const regexCapital = /\b([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+)*)/g;
  let match;

  while ((match = regexCapital.exec(text))) {
    const entity = match[1].trim();
    if (entity.length > 2 && entity !== 'El' && entity !== 'La') {
      entities.add(entity);
    }
  }

  return [...entities];
}

function cooccurrenceWeight(text: string, e1: string, e2: string): number {
  const lower = text.toLowerCase();
  const c1 = lower.includes(e1.toLowerCase());
  const c2 = lower.includes(e2.toLowerCase());
  return c1 && c2 ? 1 : 0;
}

// ============================================================================
// 3. GraphRAGBuilder Core
// ============================================================================

class GraphRAGBuilderCore {
  /**
   * Construye un grafo semántico completo a partir de:
   *   - DocumentID
   *   - Chunks extraídos previamente
   *   - Metadata
   */
  async buildFromChunks(
    documentId: string,
    chunks: string[],
    metadata: Record<string, any> = {}
  ): Promise<GraphBuildResult> {
    Logger.info('[GraphRAGBuilder] Construyendo grafo para documento', {
      documentId,
      totalChunks: chunks.length,
    });

    const nodes: GraphNode[] = [];
    const edges: GraphEdge[] = [];

    // -----------------------------------------------------------
    // 1. Crear nodo principal del documento
    // -----------------------------------------------------------
    const documentNode: GraphNode = {
      id: `doc_${documentId}`,
      type: 'document',
      label: metadata.title || `Documento ${documentId}`,
      metadata,
    };

    nodes.push(documentNode);

    // -----------------------------------------------------------
    // 2. Procesar cada chunk → nodos de chunk + entidades
    // -----------------------------------------------------------
    for (let i = 0; i < chunks.length; i++) {
      const chunk = chunks[i];
      const chunkId = `chunk_${documentId}_${i}`;

      const chunkNode: GraphNode = {
        id: chunkId,
        type: 'chunk',
        label: `Chunk ${i}`,
        metadata: {
          documentId,
          order: i,
          textPreview: chunk.slice(0, 200),
        },
        embedding: await VectorEngine.embedText(chunk),
      };

      nodes.push(chunkNode);

      // Enlace documento → chunk
      edges.push({
        source: documentNode.id!,
        target: chunkNode.id!,
        relation: 'contains',
        weight: 0.9,
      });

      // -----------------------------------------
      // Extraer entidades desde el chunk
      // -----------------------------------------
      const entities = extractEntities(chunk);

      entities.forEach((ent) => {
        const entityId = `ent_${ent.replace(/\s+/g, '_')}`;

        // Si no existe, crearlo
        if (!nodes.find((n) => n.id === entityId)) {
          nodes.push({
            id: entityId,
            type: 'entity',
            label: ent,
            metadata: { source: 'NER' },
            embedding: await VectorEngine.embedText(ent),
          });
        }

        // Crear relación chunk → entidad
        edges.push({
          source: chunkNode.id!,
          target: entityId,
          relation: 'mentions',
          weight: 0.7,
        });
      });

      // -----------------------------------------
      // Relaciones entre entidades (co-ocurrencia)
      // -----------------------------------------
      for (let a = 0; a < entities.length; a++) {
        for (let b = a + 1; b < entities.length; b++) {
          const w = cooccurrenceWeight(chunk, entities[a], entities[b]);
          if (w > 0) {
            edges.push({
              source: `ent_${entities[a].replace(/\s+/g, '_')}`,
              target: `ent_${entities[b].replace(/\s+/g, '_')}`,
              relation: 'cooccurs_with',
              weight: 0.6,
            });
          }
        }
      }
    }

    // -----------------------------------------------------------
    // 3. Integración opcional con Graphiti Server
    // -----------------------------------------------------------
    if (GRAPHITI && typeof GRAPHITI.addNodes === 'function') {
      try {
        await GRAPHITI.addNodes(nodes);
        await GRAPHITI.addEdges(edges);

        Logger.info('[GraphRAGBuilder] Grafo subido a Graphiti Server.');
      } catch (err: any) {
        Logger.error('[GraphRAGBuilder] Error subiendo grafo a Graphiti', {
          error: err.message,
        });
      }
    }

    // -----------------------------------------------------------
    // 4. Generar resumen de estructura del grafo
    // -----------------------------------------------------------
    const summary = `
Grafo creado correctamente.
- Nodos: ${nodes.length}
- Aristas: ${edges.length}
- Documento raíz: ${documentId}
- Tipos: document, chunk, entity
`;

    return {
      nodes,
      edges,
      summary,
    };
  }

  /**
   * Construye grafo directamente desde texto completo
   */
  async buildFromText(documentId: string, text: string, metadata: Record<string, any> = {}) {
    // Chunking inteligente
    const chunks = this.smartChunk(text, 1200);

    return await this.buildFromChunks(documentId, chunks, metadata);
  }

  /**
   * Chunking avanzado con división por saltos de línea y párrafos
   */
  smartChunk(text: string, maxSize: number): string[] {
    const lines = text.split('\n').map((l) => l.trim());
    const chunks: string[] = [];
    let buffer = '';

    for (const l of lines) {
      if ((buffer + '\n' + l).length > maxSize) {
        chunks.push(buffer);
        buffer = l;
      } else {
        buffer += '\n' + l;
      }
    }

    if (buffer.length > 0) chunks.push(buffer);

    return chunks;
  }
}

// ============================================================================
// 8. Export singleton
// ============================================================================

export const GraphRAGBuilder = new GraphRAGBuilderCore();
export default GraphRAGBuilder;

/**
 * GraphRAGQueryEngine.ts — AURA-MCP (Enterprise)
 * ================================================================================
 * Motor de consultas avanzadas sobre grafos + embeddings:
 *
 * Capacidades:
 *  ✔ Búsqueda por significado (vectorial)
 *  ✔ Búsqueda por conexiones en grafo (Graphiti o BD local)
 *  ✔ Reasoning multihop (2–6 saltos)
 *  ✔ Fusión vector + grafo (GraphRAG híbrido)
 *  ✔ Explicaciones paso a paso
 *  ✔ Path scoring (relevancia semántica + topología del grafo)
 *
 * Usado por:
 *   - OrchestratorCore
 *   - RAGOrchestrator
 *   - SemanticLinker
 *   - PipelineEngine (deep reasoning)
 */

import { Logger } from '../lib/logger.js';
import VectorEngine from '../integration/vectorEngine.js';
import SupabaseConnector from '../integration/supabaseConnector.js';

const GRAPHITI = (globalThis as any).AURA_GRAPHITI || null;

// ============================================================================
// 1. Tipos
// ============================================================================
export interface GraphRAGQueryOptions {
  topK?: number;
  hops?: number;
  similarityThreshold?: number;
  includeVectors?: boolean;
  includeGraph?: boolean;
  explanation?: boolean;
  metadataFilters?: Record<string, any>;
}

export interface GraphRAGAnswer {
  query: string;
  nodes: any[];
  edges: any[];
  reasoningPath: Array<string>;
  context: string;
  summary: string;
}

// ============================================================================
// 2. Utilidades internas
// ============================================================================

async function graphSearch(query: string, topK: number): Promise<any[]> {
  if (!GRAPHITI || typeof GRAPHITI.search !== 'function') return [];

  try {
    const res = await GRAPHITI.search(query, { topK });
    return res.matches || [];
  } catch (err: any) {
    Logger.error('[GraphRAGQueryEngine] Graph search error', {
      error: err.message,
    });
    return [];
  }
}

async function graphExpand(nodeId: string, hops: number): Promise<any[]> {
  if (!GRAPHITI || typeof GRAPHITI.expand !== 'function') return [];

  try {
    const res = await GRAPHITI.expand(nodeId, { depth: hops });
    return res.nodes || [];
  } catch (err: any) {
    Logger.error('[GraphRAGQueryEngine] Graph expand error', {
      error: err.message,
    });
    return [];
  }
}

// ============================================================================
// 3. Scoring híbrido
// ============================================================================

function hybridScore(vectorScore: number, graphRank: number): number {
  const vg = vectorScore * 0.65; // prioridad semántica
  const gg = (1 / (1 + graphRank)) * 0.35; // prioridad topológica
  return vg + gg;
}

// ============================================================================
// 4. Context builder
// ============================================================================
function buildContext(nodes: any[]): string {
  return nodes
    .map((n) => {
      const meta = JSON.stringify(n.metadata || {}, null, 2);
      return `### Nodo: ${n.id}\nLabel: ${n.label}\nMetadata: ${meta}\n---\n${n.text || ''}`;
    })
    .join('\n\n');
}

// ============================================================================
// 5. QueryEngine Principal
// ============================================================================

class GraphRAGQueryEngineCore {
  /**
   * Ejecuta una consulta híbrida (vector + graph) con reasoning multihop.
   */
  async query(query: string, options: GraphRAGQueryOptions = {}): Promise<GraphRAGAnswer> {
    const topK = options.topK ?? 10;
    const hops = options.hops ?? 2;
    const similarityThreshold = options.similarityThreshold ?? 0.75;

    Logger.info('[GraphRAGQueryEngine] Ejecutando consulta híbrida RAG+Graph', {
      query,
      topK,
      hops,
    });

    // ---------------------------------------------------------
    // 1. Búsqueda semántica vectorial
    // ---------------------------------------------------------
    const vectorMatches = await VectorEngine.matchEmbedding(query, topK);

    // ---------------------------------------------------------
    // 2. Búsqueda en grafo
    // ---------------------------------------------------------
    const graphMatches = await graphSearch(query, topK);

    // ---------------------------------------------------------
    // 3. Expandir nodos del grafo con multihop
    // ---------------------------------------------------------
    let expandedNodes: any[] = [];

    for (const gm of graphMatches) {
      const exp = await graphExpand(gm.id, hops);
      expandedNodes.push(...exp);
    }

    // eliminar duplicados
    const expandedMap = new Map<string, any>();
    expandedNodes.forEach((n) => expandedMap.set(n.id, n));
    expandedNodes = Array.from(expandedMap.values());

    // ---------------------------------------------------------
    // 4. Fusión híbrida vector + grafo
    // ---------------------------------------------------------
    const combined: any[] = [];

    vectorMatches.forEach((vm, idx) => {
      combined.push({
        id: vm.id,
        label: vm.metadata?.title || `doc_${vm.id}`,
        text: vm.text,
        metadata: vm.metadata,
        vectorScore: vm.score,
        graphRank: 999,
        hybrid: hybridScore(vm.score, 999),
      });
    });

    graphMatches.forEach((gm, idx) => {
      combined.push({
        id: gm.id,
        label: gm.label,
        text: gm.text,
        metadata: gm.metadata,
        vectorScore: 0,
        graphRank: idx + 1,
        hybrid: hybridScore(0, idx + 1),
      });
    });

    expandedNodes.forEach((n, idx) => {
      combined.push({
        id: n.id,
        label: n.label,
        text: n.text,
        metadata: n.metadata,
        vectorScore: 0.1,
        graphRank: idx + 3,
        hybrid: hybridScore(0.1, idx + 3),
      });
    });

    // ---------------------------------------------------------
    // 5. Ranking por score híbrido
    // ---------------------------------------------------------
    const ranked = combined.sort((a, b) => b.hybrid - a.hybrid).slice(0, topK);

    // ---------------------------------------------------------
    // 6. Build context
    // ---------------------------------------------------------
    const context = buildContext(ranked);

    // ---------------------------------------------------------
    // 7. Reasoning path (explicación)
    // ---------------------------------------------------------
    const reasoningPath: string[] = [];

    if (options.explanation) {
      reasoningPath.push('1. Se ejecutó búsqueda vectorial de embeddings.');
      reasoningPath.push('2. Se ejecutó búsqueda en grafo usando Graphiti.');
      reasoningPath.push(`3. Se expandió hasta ${hops} hops.`);
      reasoningPath.push('4. Se fusionaron resultados con scoring híbrido.');
      reasoningPath.push('5. Se generó contexto consolidado para LLM.');
    }

    return {
      query,
      nodes: ranked,
      edges: [], // opcionalmente podemos recuperar edges en otra versión
      reasoningPath,
      context,
      summary: `Consulta híbrida completada: ${ranked.length} nodos relevantes.`,
    };
  }

  /**
   * Consulta multihop pura basada solo en expansión de grafo.
   */
  async multihop(startNodeId: string, hops: number = 3) {
    const nodes = await graphExpand(startNodeId, hops);

    return {
      startNode: startNodeId,
      depth: hops,
      nodes,
      summary: `Expansión multihop desde ${startNodeId} completada.`,
    };
  }

  /**
   * razonamiento semántico directo entre dos textos
   */
  async relate(textA: string, textB: string) {
    const embA = await VectorEngine.embedText(textA);
    const embB = await VectorEngine.embedText(textB);

    const dot = embA.reduce((acc, v, i) => acc + v * embB[i], 0);

    return {
      score: dot,
      strong: dot >= 0.82,
      summary: dot >= 0.82 ? 'Altamente relacionados' : 'Relación débil',
    };
  }
}

