export const GraphRAGQueryEngine = new GraphRAGQueryEngineCore();
export default GraphRAGQueryEngine;

import type { AgentDefinition } from './agentRegistry';
import { Logger } from '../src/lib/logger';
import { buildForAgent } from '../src/AgentPromptInjector';

type AgentInstance = any;

function createLangChainExecutor(
  def: AgentDefinition,
  prompt: string,
  registry: any
): AgentInstance {
  return {
    definition: def,
    prompt,
    registry,
    exec: async (input: any) => ({ ok: true, input }),
  };
}

export class AgentFactory {
  constructor(
    private registry: { get: (name: string) => AgentDefinition | null },
    private logger: typeof Logger,
    private promptInjector: { buildForAgent: (def: AgentDefinition, opts?: any) => Promise<string> }
  ) {}

  async createAgent(name: string, context?: Record<string, any>): Promise<AgentInstance> {
    this.logger.debug('agentFactory.createAgent.start', { name });
    const definition = this.registry.get(name);
    if (!definition) {
      this.logger.error('agentFactory.createAgent.notFound', { name });
      throw new Error(`Agent ${name} not found`);
    }

    try {
      const prompt = await this.promptInjector.buildForAgent(definition, { data: context ?? {} });
      this.logger.debug('agentFactory.createAgent.promptBuilt', {
        name,
        promptLength: prompt?.length ?? 0,
      });
      const instance = createLangChainExecutor(definition, prompt, this.registry);
      this.logger.info('agentFactory.createAgent.created', { name });
      return instance;
    } catch (err) {
      this.logger.error('agentFactory.createAgent.error', {
        name,
        error: (err as Error).message ?? err,
      });
      throw err;
    }
  }
}

import { AgentRegistry, AgentDefinition } from './agentRegistry';
import { AgentFactory } from './agentFactory';
import { Logger } from '../src/lib/logger';

type AgentInstance = any;

export class AgentManager {
  private registry: AgentRegistry;
  private factory: AgentFactory;
  private logger: typeof Logger;

  constructor(options?: {
    registry?: AgentRegistry;
    factory?: AgentFactory;
    logger?: typeof Logger;
    promptInjector?: any;
  }) {
    this.registry = options?.registry ?? new AgentRegistry();
    this.logger = options?.logger ?? Logger;
    const promptInjector = options?.promptInjector ?? {
      buildForAgent: async (_d: AgentDefinition, _o?: any) => '',
    };
    this.factory = options?.factory ?? new AgentFactory(this.registry, this.logger, promptInjector);
  }

  register(agent: AgentDefinition): void {
    this.logger.debug('agentManager.register.start', { name: agent.name });
    this.registry.register(agent);
    this.logger.info('agentManager.registered', { name: agent.name });
  }

  registerAll(agents: AgentDefinition[]): void {
    for (const a of agents) {
      try {
        this.register(a);
      } catch (err) {
        this.logger.warn('agentManager.registerAll.skip', {
          name: a.name,
          reason: (err as Error).message,
        });
      }
    }
  }

  async create(name: string, context?: Record<string, any>): Promise<AgentInstance> {
    this.logger.debug('agentManager.create.start', { name });
    const instance = await this.factory.createAgent(name, context);
    this.logger.info('agentManager.create.finished', { name });
    return instance;
  }

  getDefinition(name: string): AgentDefinition | null {
    return this.registry.get(name);
  }

  listDefinitions(): AgentDefinition[] {
    return this.registry.list();
  }

  unregister(name: string): boolean {
    const removed = this.registry.unregister(name);
    if (removed) this.logger.info('agentManager.unregistered', { name });
    return removed;
  }

  clearRegistry(): void {
    this.registry.clear();
    this.logger.info('agentManager.clearedRegistry');
  }

  // --- Static Singleton for Legacy/Global Access ---
  private static instance: AgentManager;

  static getInstance(): AgentManager {
    if (!AgentManager.instance) {
      AgentManager.instance = new AgentManager();
    }
    return AgentManager.instance;
  }

  static register(agent: AgentDefinition): void {
    this.getInstance().register(agent);
  }

  static get(name: string): AgentDefinition | null {
    return this.getInstance().getDefinition(name);
  }

  static list(): AgentDefinition[] {
    return this.getInstance().listDefinitions();
  }

  static unregister(name: string): boolean {
    return this.getInstance().unregister(name);
  }
}

