/**
 * deploymentManager.ts — AURA-MCP
 * ================================================================================
 * Gestor de entornos y despliegue para módulos MCP+IA.
 *
 * Alineado con la Plantilla MCP IA Modular:
 *  - Entornos: local, dev, staging, prod
 *  - Versionado por entorno
 *  - CI/CD por módulo
 *  - Estrategias de despliegue (blue/green, rolling, simple, canary)
 *
 * Este módulo NO ejecuta el despliegue físico (docker, k8s, etc.),
 * sino que:
 *   ✔ Modela los targets y entornos
 *   ✔ Mantiene qué versión está desplegada en cada entorno
 *   ✔ Genera planes de despliegue
 *   ✔ Registra estado de despliegue, health y metadatos de CI/CD
 */

import { Logger } from '../lib/logger.js';
import ModuleRegistry, { ModuleRecord } from './moduleRegistry.js';
import { EnvModeEnum } from './mcpModuleBlueprint.js';

// =============================================================================
// 1. ENUMS Y TIPOS BÁSICOS
// =============================================================================

export type EnvStage = 'local' | 'dev' | 'staging' | 'prod';

export const EnvStageOrder: EnvStage[] = ['local', 'dev', 'staging', 'prod'];

export type DeployStrategy = 'simple' | 'blue_green' | 'rolling' | 'canary';

export type DeployStatus = 'pending' | 'in_progress' | 'success' | 'failed' | 'cancelled';

export interface DeploymentTarget {
  id: string; // id interno: prod-main, staging-eu, etc.
  name: string; // nombre humano
  env: EnvStage;
  baseUrl?: string; // URL pública o base
  description?: string;
  isDefault?: boolean;
  tags?: string[]; // ej: ["aura-core", "latam", "critical"]
  ciPipelineUrl?: string; // URL a la pipeline de CI/CD
  infra?: string; // docker, k8s, vm, serverless, etc.
  lastHealthStatus?: 'unknown' | 'healthy' | 'degraded' | 'down';
  lastDeployedAt?: string;
  lastDeployedVersion?: string | null; // versionId del módulo principal, si aplica
}

// Registro de qué módulo está desplegado en qué entorno/target
export interface ModuleDeploymentRecord {
  moduleId: string;
  versionId: string;
  env: EnvStage;
  targetId: string;
  status: DeployStatus;
  strategy: DeployStrategy;
  deployedAt: string;
  deployedBy?: string;
  notes?: string;
}

// Plan de despliegue calculado antes de ejecutar
export interface DeployPlan {
  moduleId: string;
  versionId: string;
  env: EnvStage;
  target: DeploymentTarget;
  strategy: DeployStrategy;
  steps: string[];
  risks: string[];
  preChecks: string[];
  postChecks: string[];
}

// =============================================================================
// 2. GESTOR PRINCIPAL
// =============================================================================

class DeploymentManagerCore {
  private targets: Map<string, DeploymentTarget> = new Map();
  private deployments: ModuleDeploymentRecord[] = [];

  // -------------------------------------------------------------------------
  // CONFIG / INIT
  // -------------------------------------------------------------------------

  bootstrapDefaultTargets() {
    // Targets de ejemplo; puedes ajustarlos a tu realidad
    this.registerTarget({
      id: 'local-core',
      name: 'Local Core AURA',
      env: 'local',
      baseUrl: 'http://localhost:3000',
      description: 'Entorno de desarrollo local de AURA.',
      isDefault: true,
      tags: ['aura-core', 'local'],
      infra: 'docker',
      lastHealthStatus: 'unknown',
      lastDeployedVersion: null,
    });

    this.registerTarget({
      id: 'dev-core',
      name: 'Dev AURA Core',
      env: 'dev',
      baseUrl: 'https://dev-aura-core.yourdomain.com',
      description: 'Entorno de integración / pruebas internas.',
      tags: ['aura-core', 'dev'],
      infra: 'docker',
      lastHealthStatus: 'unknown',
      lastDeployedVersion: null,
    });

    this.registerTarget({
      id: 'staging-core',
      name: 'Staging AURA Core',
      env: 'staging',
      baseUrl: 'https://staging-aura-core.yourdomain.com',
      description: 'Entorno Pre-Producción.',
      tags: ['aura-core', 'staging'],
      infra: 'kubernetes',
      lastHealthStatus: 'unknown',
      lastDeployedVersion: null,
    });

    this.registerTarget({
      id: 'prod-core',
      name: 'Prod AURA Core',
      env: 'prod',
      baseUrl: 'https://aura-core.yourdomain.com',
      description: 'Entorno de Producción.',
      tags: ['aura-core', 'prod', 'critical'],
      infra: 'kubernetes',
      lastHealthStatus: 'unknown',
      lastDeployedVersion: null,
    });

    Logger.info('[DeploymentManager] Targets default inicializados.');
  }

  // -------------------------------------------------------------------------
  // TARGETS
  // -------------------------------------------------------------------------

  registerTarget(target: DeploymentTarget): DeploymentTarget {
    this.targets.set(target.id, target);
    Logger.info('[DeploymentManager] Target registrado/actualizado', target);
    return target;
  }

  getTarget(targetId: string): DeploymentTarget | undefined {
    return this.targets.get(targetId);
  }

  listTargets(env?: EnvStage): DeploymentTarget[] {
    const all = Array.from(this.targets.values());
    return env ? all.filter((t) => t.env === env) : all;
  }

  getDefaultTarget(env: EnvStage): DeploymentTarget | undefined {
    const envTargets = this.listTargets(env);
    const explicitDefault = envTargets.find((t) => t.isDefault);
    return explicitDefault || envTargets[0];
  }

  // -------------------------------------------------------------------------
  // PLANIFICACIÓN DE DESPLIEGUE
  // -------------------------------------------------------------------------

  createDeployPlan(params: {
    moduleId: string;
    versionId?: string;
    env: EnvStage;
    targetId?: string;
    strategy?: DeployStrategy;
  }): DeployPlan | null {
    const { moduleId, env } = params;
    const versionId = params.versionId || 'default';
    const strategy: DeployStrategy = params.strategy || 'simple';

    // 1. Verificar que el módulo existe en el registry
    const moduleRec: ModuleRecord | undefined = ModuleRegistry.get(moduleId, versionId);

    if (!moduleRec) {
      Logger.error('[DeploymentManager] Módulo no encontrado para despliegue', {
        moduleId,
        versionId,
      });
      return null;
    }

    // 2. Resolver target
    let target: DeploymentTarget | undefined;

    if (params.targetId) {
      target = this.getTarget(params.targetId);
    } else {
      target = this.getDefaultTarget(env);
    }

    if (!target) {
      Logger.error('[DeploymentManager] No existe target para el entorno', {
        env,
      });
      return null;
    }

    // 3. Construir plan de despliegue
    const steps: string[] = [];
    const risks: string[] = [];
    const preChecks: string[] = [];
    const postChecks: string[] = [];

    preChecks.push(
      'Verificar que el módulo pasa validación de blueprint.',
      'Revisar compatibilidad de versión (breaking changes).',
      'Confirmar que no hay despliegues simultáneos en el mismo target.'
    );

    // Estrategia específica
    switch (strategy) {
      case 'simple':
        steps.push(
          'Construir imagen / artefacto del módulo.',
          `Desplegar versión ${versionId} en target ${target.id}.`,
          'Actualizar registros de ModuleRegistry / DeploymentManager.'
        );
        risks.push('Interrupción breve posible.', 'Rollback manual si no se automatiza.');
        break;

      case 'blue_green':
        steps.push(
          'Desplegar nueva versión en stack paralelo (green).',
          'Ejecutar smoke tests y pruebas de regresión en green.',
          'Cambiar tráfico gradualmente de blue → green.',
          'Desmantelar stack antiguo (blue) una vez estable.'
        );
        risks.push(
          'Mayor consumo de recursos durante despliegue.',
          'Complejidad en manejo de tráfico y monitoreo.'
        );
        break;

      case 'rolling':
        steps.push(
          'Actualizar pods/instancias en batches pequeños.',
          'Monitorear health tras cada batch.',
          'Completar cuando el 100% de instancias estén en nueva versión.'
        );
        risks.push(
          'Puede ser más lento completar despliegue.',
          'Riesgo de estados mixtos si falla a mitad de camino.'
        );
        break;

      case 'canary':
        steps.push(
          'Desplegar nueva versión a una fracción pequeña de tráfico.',
          'Monitorear métricas clave (errores, latencia, negocio).',
          'Aumentar gradualmente el porcentaje de tráfico.',
          'Promocionar a full o hacer rollback según resultados.'
        );
        risks.push(
          'Requiere infraestructura de routing avanzada.',
          'Necesita métricas claras para decisión de promoción.'
        );
        break;
    }

    postChecks.push(
      'Verificar logs y métricas de error.',
      'Confirmar integración con módulos dependientes.',
      'Notificar al responsable del despliegue / canal de alerta.'
    );

    const plan: DeployPlan = {
      moduleId,
      versionId,
      env,
      target,
      strategy,
      steps,
      risks,
      preChecks,
      postChecks,
    };

    Logger.info('[DeploymentManager] Plan de despliegue generado', plan);

    return plan;
  }

  // -------------------------------------------------------------------------
  // REGISTRAR DESPLIEGUE COMPLETADO / FALLIDO
  // -------------------------------------------------------------------------

  registerDeployment(result: {
    moduleId: string;
    versionId: string;
    env: EnvStage;
    targetId: string;
    status: DeployStatus;
    strategy: DeployStrategy;
    deployedBy?: string;
    notes?: string;
  }): ModuleDeploymentRecord {
    const record: ModuleDeploymentRecord = {
      moduleId: result.moduleId,
      versionId: result.versionId,
      env: result.env,
      targetId: result.targetId,
      status: result.status,
      strategy: result.strategy,
      deployedAt: new Date().toISOString(),
      deployedBy: result.deployedBy,
      notes: result.notes,
    };

    this.deployments.push(record);

    // Actualizar metadata en el target
    const target = this.targets.get(result.targetId);
    if (target) {
      target.lastDeployedAt = record.deployedAt;
      if (result.status === 'success') {
        target.lastDeployedVersion = result.versionId;
        target.lastHealthStatus = 'healthy';
      } else if (result.status === 'failed') {
        target.lastHealthStatus = 'degraded';
      }
      this.targets.set(target.id, target);
    }

    Logger.info('[DeploymentManager] Registro de despliegue actualizado', record);

    return record;
  }

  // -------------------------------------------------------------------------
  // CONSULTAS
  // -------------------------------------------------------------------------

  getDeploymentsForModule(moduleId: string, env?: EnvStage): ModuleDeploymentRecord[] {
    return this.deployments.filter((d) => d.moduleId === moduleId && (!env || d.env === env));
  }

  getCurrentVersionForModule(moduleId: string, env: EnvStage): string | null {
    const envDeploys = this.deployments
      .filter((d) => d.moduleId === moduleId && d.env === env)
      .sort((a, b) => (a.deployedAt > b.deployedAt ? -1 : 1));

    const lastSuccess = envDeploys.find((d) => d.status === 'success');
    return lastSuccess ? lastSuccess.versionId : null;
  }

  listDeployments(): ModuleDeploymentRecord[] {
    return [...this.deployments];
  }

  // Snapshot de estado útil para dashboards de observabilidad
  snapshot() {
    return {
      targets: Array.from(this.targets.values()),
      deployments: this.deployments,
    };
  }
}

// =============================================================================
// 3. SINGLETON EXPORTADO
// =============================================================================

export const DeploymentManager = new DeploymentManagerCore();

// Inicializa targets default
DeploymentManager.bootstrapDefaultTargets();

export default DeploymentManager;

/**
 * moduleLoader.ts — AURA-MCP
 * ==============================================================================
 * Cargador dinámico de módulos MCP+IA basado en:
 *    ✔ entorno (local / staging / prod)
 *    ✔ cliente (contextId)
 *    ✔ canal (web, mobile, discord, api)
 *    ✔ versión (semver o default)
 *    ✔ tags, tipo, propiedades declaradas en el blueprint
 *
 * Alineado con:
 *  - Plantilla MCP IA Modular.pdf  (env, varios entornos, versionado)
 *  - AURA-MCP Registry
 */

import fs from 'fs';
import path from 'path';

import { Logger } from '../lib/logger.js';
import ModuleRegistry, { ModuleQuery, ModuleRecord } from './moduleRegistry.js';

import { McpModuleBlueprint, McpModuleBlueprintSchema } from './mcpModuleBlueprint.js';

export interface LoaderOptions {
  envMode?: string; // local | staging | prod
  contextId?: string; // cliente o tenant
  channel?: string; // web | mobile | discord | api
  versionId?: string; // semver
  moduleId?: string; // ID del módulo
  tags?: string[]; // filtros extra
  types?: string[]; // agent | ui | gateway | core
  enabledOnly?: boolean;
}

export interface ModuleLoadResult {
  resolved: ModuleRecord | null;
  fallback?: string;
  error?: string;
  searchQuery: LoaderOptions;
}

// ============================================================================
// 1. Load from Registry (core)
// ============================================================================

export class ModuleLoader {
  /**
   * Búsqueda con lógica de priorización basada en:
   *   1. moduleId + version + context + env
   *   2. moduleId + default version
   *   3. any version but matching context
   *   4. fallback global
   */
  static load(options: LoaderOptions): ModuleLoadResult {
    const {
      moduleId,
      versionId,
      contextId,
      channel,
      envMode = 'local',
      tags,
      types,
      enabledOnly = true,
    } = options;

    Logger.info('[ModuleLoader] Resolviendo módulo...', options);

    // 1. Query base para ModuleRegistry
    const query: ModuleQuery = {
      moduleId: moduleId || undefined,
      versionId: versionId || undefined,
      contextId: contextId || undefined,
      envMode,
      tags: tags || undefined,
      types: types as any,
      enabledOnly,
    };

    let candidates = ModuleRegistry.list(query);

    // Si vino canal, filtrar por metadata del blueprint
    if (channel) {
      candidates = candidates.filter((m) =>
        m.blueprint?.architecture?.uiResponseContract?.metadata?.channels
          ? m.blueprint.architecture.uiResponseContract.metadata.channels.includes(channel)
          : true
      );
    }

    // Caso directo: hubo coincidencias
    if (candidates.length > 0) {
      return {
        resolved: candidates[0],
        searchQuery: options,
      };
    }

    // ----------------------------------------------------------------------
    // 2. No hubo coincidencias → intentar fallback por versión
    // ----------------------------------------------------------------------
    if (moduleId) {
      const fallback = ModuleRegistry.get(moduleId, 'default');
      if (fallback) {
        return {
          resolved: fallback,
          fallback: 'default-version',
          searchQuery: options,
        };
      }
    }

    // ----------------------------------------------------------------------
    // 3. Intentar coincidencias por contexto sin versión
    // ----------------------------------------------------------------------
    if (contextId && moduleId) {
      const contextCandidates = ModuleRegistry.list({
        moduleId,
        contextId,
        enabledOnly,
      });

      if (contextCandidates.length > 0) {
        return {
          resolved: contextCandidates[0],
          fallback: 'context-no-version',
          searchQuery: options,
        };
      }
    }

    // ----------------------------------------------------------------------
    // 4. Fallback global: cualquier módulo con el mismo moduleId
    // ----------------------------------------------------------------------
    if (moduleId) {
      const globalMatch = ModuleRegistry.list({
        moduleId,
        enabledOnly,
      });

      if (globalMatch.length > 0) {
        return {
          resolved: globalMatch[0],
          fallback: 'global-any-version',
          searchQuery: options,
        };
      }
    }

    // ----------------------------------------------------------------------
    // 5. Fallback universal
    // ----------------------------------------------------------------------
    return {
      resolved: null,
      error: 'No se encontró ningún módulo compatible',
      searchQuery: options,
    };
  }

  // ============================================================================
  // 2. Load module from file
  // ============================================================================

  static loadFromFile(filePath: string): ModuleRecord | null {
    try {
      const abs = path.resolve(filePath);
      const raw = fs.readFileSync(abs, 'utf8');
      const json = JSON.parse(raw);

      // Validar blueprint
      const validated = McpModuleBlueprintSchema.parse(json);

      // Registrar módulo en runtime
      const record = ModuleRegistry.register(validated);

      Logger.info('[ModuleLoader] Módulo cargado desde archivo', { file: abs });
      return record;
    } catch (err: any) {
      Logger.error('[ModuleLoader] Error al cargar archivo', {
        error: err.message,
        file: filePath,
      });
      return null;
    }
  }

  // ============================================================================
  // 3. Load all modules from a directory
  // ============================================================================

  static loadDirectory(dir: string): number {
    const abs = path.resolve(dir);
    const files = fs.readdirSync(abs);

    let count = 0;

    for (const file of files) {
      const full = path.join(abs, file);
      if (file.endsWith('.json')) {
        const loaded = this.loadFromFile(full);
        if (loaded) count++;
      }
    }

    Logger.info('[ModuleLoader] Directorio cargado', {
      dir: abs,
      total: count,
    });

    return count;
  }

  // ============================================================================
  // 4. Hot Reload de un módulo individual
  // ============================================================================

  static hotReload(moduleId: string, versionId: string = 'default'): ModuleRecord | null {
    const record = ModuleRegistry.get(moduleId, versionId);

    if (!record) {
      Logger.warn('[ModuleLoader] No existe módulo para recargar', {
        moduleId,
        versionId,
      });
      return null;
    }

    try {
      // Re-parsear blueprint
      const revalidated = McpModuleBlueprintSchema.parse(record.blueprint);

      // Re-registrar
      const updated = ModuleRegistry.register(revalidated);

      Logger.info('[ModuleLoader] Hot reload completado', {
        moduleId,
        versionId,
      });
      return updated;
    } catch (err: any) {
      Logger.error('[ModuleLoader] Falló hot reload', {
        moduleId,
        versionId,
        error: err.message,
      });
      return null;
    }
  }
}

export default ModuleLoader;

/**
 * moduleRegistry.ts — AURA-MCP
 * ============================================================================
 * Registro central de módulos MCP+IA basados en la Plantilla MCP IA Modular.
 *
 * Cada módulo se describe mediante un McpModuleBlueprint y queda accesible
 * para:
 *   - ModuleRouter
 *   - PipelineEngine
 *   - OrchestratorCore
 *   - UIs JSON-driven
 *
 * Alineado con:
 *   - Plantilla Mcp Ia Modular.pdf
 *   - Prompt System Filtrados
 *   - Arquitectura AURA-MCP Core
 */

import fs from 'fs';
import path from 'path';

import { Logger } from '../lib/logger.js';
import {
  McpModuleBlueprint,
  McpModuleBlueprintSchema,
  validateMcpModuleBlueprint,
} from './mcpModuleBlueprint.js';
import { EnvModeEnum, ModuleTypeEnum } from './mcpModuleBlueprint.js';

// ---------------------------------------------------------------------------
// 1. Tipos internos del Registry
// ---------------------------------------------------------------------------

export type ModuleKey = string; // forma: moduleId@versionId (o @default)

export interface ModuleRecord {
  key: ModuleKey;
  moduleId: string;
  versionId: string; // semver o "default"
  contextId?: string | null; // cliente, región, etc.
  envMode: string; // local / staging / prod…
  enabled: boolean;
  tags: string[];
  blueprint: McpModuleBlueprint;
  createdAt: string;
  updatedAt: string;
}

// Filtros de consulta
export interface ModuleQuery {
  moduleId?: string;
  versionId?: string;
  contextId?: string;
  envMode?: string;
  tags?: string[];
  types?: (typeof ModuleTypeEnum._type)[];
  enabledOnly?: boolean;
}

// ---------------------------------------------------------------------------
// 2. Helpers internos
// ---------------------------------------------------------------------------

function buildModuleKey(moduleId: string, versionId?: string | null): ModuleKey {
  return `${moduleId}@${versionId || 'default'}`;
}

function nowISO() {
  return new Date().toISOString();
}

// ---------------------------------------------------------------------------
// 3. ModuleRegistry — Singleton
// ---------------------------------------------------------------------------

class ModuleRegistryCore {
  private modules: Map<ModuleKey, ModuleRecord> = new Map();

  // -----------------------------------------------------------------------
  // Registrar / actualizar módulo (upsert)
  // -----------------------------------------------------------------------
  register(blueprint: McpModuleBlueprint): ModuleRecord {
    // Extraemos identificadores desde la plantilla
    const moduleId = blueprint.cloning?.module_id || blueprint.purpose.moduleId;

    const versionId = blueprint.cloning?.version_id || 'default';

    const contextId = blueprint.cloning?.context_id ?? null;

    const envMode = blueprint.env?.mode || EnvModeEnum.Enum.local;

    const tags = blueprint.cloning?.tags || [];

    const key = buildModuleKey(moduleId, versionId);
    const existing = this.modules.get(key);

    const record: ModuleRecord = {
      key,
      moduleId,
      versionId,
      contextId: contextId || undefined,
      envMode,
      enabled: true,
      tags,
      blueprint,
      createdAt: existing?.createdAt || nowISO(),
      updatedAt: nowISO(),
    };

    this.modules.set(key, record);

    if (existing) {
      Logger.info('[ModuleRegistry] Módulo actualizado', { key, envMode, tags });
    } else {
      Logger.info('[ModuleRegistry] Módulo registrado', { key, envMode, tags });
    }

    return record;
  }

  // -----------------------------------------------------------------------
  // Registrar a partir de un objeto ANY (con validación)
  // -----------------------------------------------------------------------
  registerRaw(data: any): ModuleRecord {
    const validated = validateMcpModuleBlueprint(data);
    return this.register(validated);
  }

  // -----------------------------------------------------------------------
  // Cargar módulo desde archivo JSON (o .mcp.json en el futuro)
  // -----------------------------------------------------------------------
  registerFromFile(filePath: string): ModuleRecord | null {
    try {
      const abs = path.resolve(filePath);
      const content = fs.readFileSync(abs, 'utf8');
      const json = JSON.parse(content);

      const validated = McpModuleBlueprintSchema.parse(json);
      const rec = this.register(validated);

      Logger.info('[ModuleRegistry] Módulo registrado desde archivo', {
        file: abs,
        key: rec.key,
      });

      return rec;
    } catch (err: any) {
      Logger.error('[ModuleRegistry] Error al registrar módulo desde archivo', {
        file: filePath,
        error: err.message,
      });
      return null;
    }
  }

  // -----------------------------------------------------------------------
  // Obtener un módulo por id + versión
  // -----------------------------------------------------------------------
  get(moduleId: string, versionId?: string | null): ModuleRecord | undefined {
    const key = buildModuleKey(moduleId, versionId);
    return this.modules.get(key);
  }

  // Versión “inteligente”: si no encuentra versión específica,
  // intenta "default".
  getSmart(moduleId: string, versionId?: string | null): ModuleRecord | undefined {
    if (versionId) {
      const exact = this.get(moduleId, versionId);
      if (exact) return exact;
    }
    return this.get(moduleId, 'default');
  }

  // -----------------------------------------------------------------------
  // Habilitar / deshabilitar módulo
  // -----------------------------------------------------------------------
  enable(moduleId: string, versionId?: string | null): void {
    const key = buildModuleKey(moduleId, versionId);
    const rec = this.modules.get(key);
    if (!rec) return;

    rec.enabled = true;
    rec.updatedAt = nowISO();
    this.modules.set(key, rec);

    Logger.info('[ModuleRegistry] Módulo habilitado', { key });
  }

  disable(moduleId: string, versionId?: string | null): void {
    const key = buildModuleKey(moduleId, versionId);
    const rec = this.modules.get(key);
    if (!rec) return;

    rec.enabled = false;
    rec.updatedAt = nowISO();
    this.modules.set(key, rec);

    Logger.warn('[ModuleRegistry] Módulo deshabilitado', { key });
  }

  // -----------------------------------------------------------------------
  // Listar módulos con filtros
  // -----------------------------------------------------------------------
  list(query: ModuleQuery = {}): ModuleRecord[] {
    const { moduleId, versionId, contextId, envMode, tags, types, enabledOnly } = query;

    let items = Array.from(this.modules.values());

    if (moduleId) {
      items = items.filter((m) => m.moduleId === moduleId);
    }
    if (versionId) {
      items = items.filter((m) => m.versionId === versionId);
    }
    if (contextId) {
      items = items.filter((m) => m.contextId === contextId);
    }
    if (envMode) {
      items = items.filter((m) => m.envMode === envMode);
    }
    if (enabledOnly) {
      items = items.filter((m) => m.enabled);
    }
    if (tags && tags.length > 0) {
      items = items.filter((m) => tags.every((t) => m.tags.includes(t)));
    }
    if (types && types.length > 0) {
      items = items.filter((m) => m.blueprint.purpose.types.some((t) => types.includes(t)));
    }

    return items;
  }

  // -----------------------------------------------------------------------
  // Búsqueda por tag / tipo / entorno (helpers comunes)
  // -----------------------------------------------------------------------
  findByTag(tag: string): ModuleRecord[] {
    return this.list({ tags: [tag] });
  }

  findByType(type: typeof ModuleTypeEnum._type): ModuleRecord[] {
    return this.list({ types: [type] });
  }

  findByEnv(envMode: string): ModuleRecord[] {
    return this.list({ envMode });
  }

  // -----------------------------------------------------------------------
  // Exportación del estado del registry (para debugging / observabilidad)
  // -----------------------------------------------------------------------
  snapshot() {
    return this.list().map(({ blueprint, ...rest }) => rest);
  }
}

// ---------------------------------------------------------------------------
// 4. Singleton exportado
// ---------------------------------------------------------------------------

export const ModuleRegistry = new ModuleRegistryCore();

export default ModuleRegistry;

/**
 * moduleRouter.ts — AURA-MCP
 * ================================================================================
 * Router cognitivo entre módulos MCP+IA.
 *
 * Este módulo implementa el "Dispatcher" descrito en la Plantilla MCP+IA:
 *   - Un mensaje puede activar un módulo concreto, o derivarse a otro.
 *   - Soporta encadenamiento: módulo → agente → módulo siguiente.
 *
 * Alineado con:
 *   • Dispatcher (submódulos / agentes) — PDF
 *     【turn3file1†Plantilla Mcp Ia Modular.pdf†L36-L37】
 *
 *   • Ciclo de vida MCP+AURA → routing entre módulos
 *     【turn3file11†Plantilla Mcp Ia Modular.pdf†L48-L62】
 */

import { Logger } from '../lib/logger.js';
import ModuleRegistry from './moduleRegistry.js';
import ModuleLoader, { LoaderOptions } from './moduleLoader.js';

export interface RoutingInput {
  text: string; // mensaje del usuario o evento
  contextId?: string; // cliente
  channel?: string; // api, mobile, web, etc.
  envMode?: string; // local / staging / prod
  currentModuleId?: string; // módulo actual en el flujo
  suggestedNextModule?: string; // módulo que el agente sugirió como next-module
  tags?: string[]; // clasificación semántica previa
  metadata?: any;
}

export interface RoutingDecision {
  moduleId: string | null;
  versionId?: string | null;
  source: string; // cómo se decidió (user → tags → module → fallback)
  resolved: any;
  error?: string | null;
}

/**
 * ModuleRouter — decide qué módulo debe ejecutarse.
 */
export class ModuleRouter {
  /**
   * DECISIÓN PRINCIPAL:
   * 1. Si el input sugiere un "next-module" → úsalo.
   * 2. Si existe módulo específico para tenant/contexto → úsalo.
   * 3. Si existe módulo por canal → úsalo.
   * 4. Si el input matchea tags → úsalo.
   * 5. Caso contrario: "default" o módulo global.
   */
  static decide(input: RoutingInput): RoutingDecision {
    Logger.info('[ModuleRouter] Resolviendo módulo para input...', {
      text_preview: input.text.slice(0, 120),
      contextId: input.contextId,
      channel: input.channel,
      suggestedNextModule: input.suggestedNextModule,
    });

    // =========================================================================
    // 1. NEXT-MODULE sugerido por el agente / pipeline
    // =========================================================================
    if (input.suggestedNextModule) {
      const next = ModuleRegistry.getSmart(input.suggestedNextModule);
      if (next) {
        return {
          moduleId: next.moduleId,
          versionId: next.versionId,
          resolved: next,
          source: 'suggested-next-module',
        };
      }
    }

    // =========================================================================
    // 2. MÓDULO ACTUAL SUGIERE SUCESOR
    //    El PDF dice: “Un módulo puede derivar según estado del flujo”
    //    Ej: onboarding → billing → activación
    // =========================================================================
    if (input.currentModuleId) {
      const current = ModuleRegistry.getSmart(input.currentModuleId);
      const nextId = current?.blueprint.architecture?.uiResponseContract?.metadata?.next_module;

      if (nextId) {
        const nextModule = ModuleRegistry.getSmart(nextId);
        if (nextModule) {
          return {
            moduleId: nextModule.moduleId,
            versionId: nextModule.versionId,
            resolved: nextModule,
            source: 'module-derived-next',
          };
        }
      }
    }

    // =========================================================================
    // 3. BÚSQUEDA POR CONTEXTO (tenant / cliente / región)
    // =========================================================================
    if (input.contextId) {
      const contextual = ModuleRegistry.list({
        contextId: input.contextId,
        enabledOnly: true,
      });

      if (contextual.length > 0) {
        return {
          moduleId: contextual[0].moduleId,
          versionId: contextual[0].versionId,
          resolved: contextual[0],
          source: 'context-match',
        };
      }
    }

    // =========================================================================
    // 4. BÚSQUEDA POR CANAL (web / mobile / discord / api)
    //    El PDF dice: “El módulo puede variar según canal”.
    // =========================================================================
    if (input.channel) {
      const byChannel = ModuleRegistry.list({
        enabledOnly: true,
      }).filter((m) =>
        m.blueprint?.architecture?.uiResponseContract?.metadata?.channels?.includes(input.channel)
      );

      if (byChannel.length > 0) {
        return {
          moduleId: byChannel[0].moduleId,
          versionId: byChannel[0].versionId,
          resolved: byChannel[0],
          source: 'channel-match',
        };
      }
    }

    // =========================================================================
    // 5. BÚSQUEDA POR TAGS SEMÁNTICAS
    //    El PDF dice: “clasificación por tags → filtrado”
    // =========================================================================
    if (input.tags && input.tags.length > 0) {
      const matches = ModuleRegistry.list({
        tags: input.tags,
        enabledOnly: true,
      });

      if (matches.length > 0) {
        return {
          moduleId: matches[0].moduleId,
          versionId: matches[0].versionId,
          resolved: matches[0],
          source: 'tag-match',
        };
      }
    }

    // =========================================================================
    // 6. INTENTION-BASED ROUTING (pequeña heurística)
    //    Dado que el PDF incluye clasificación semántica,
    //    permitimos reglas simples (ejemplos reales).
    // =========================================================================
    const lower = input.text.toLowerCase();

    if (lower.includes('onboarding')) {
      const onboarding = ModuleRegistry.getSmart('onboarding');
      if (onboarding) {
        return {
          moduleId: onboarding.moduleId,
          versionId: onboarding.versionId,
          resolved: onboarding,
          source: 'intent-onboarding',
        };
      }
    }

    if (lower.includes('diagnóstico') || lower.includes('diagnostico')) {
      const diag = ModuleRegistry.getSmart('diagnostico_empresarial');
      if (diag) {
        return {
          moduleId: diag.moduleId,
          versionId: diag.versionId,
          resolved: diag,
          source: 'intent-diagnostico',
        };
      }
    }

    if (lower.includes('documento') || lower.includes('pdf') || lower.includes('factura')) {
      const doc = ModuleRegistry.getSmart('document_processing');
      if (doc) {
        return {
          moduleId: doc.moduleId,
          versionId: doc.versionId,
          resolved: doc,
          source: 'intent-documents',
        };
      }
    }

    // =========================================================================
    // 7. Fallback: cargar un módulo estándar
    // =========================================================================
    const std = ModuleRegistry.getSmart('default');
    if (std) {
      return {
        moduleId: std.moduleId,
        versionId: std.versionId,
        resolved: std,
        source: 'fallback-default',
      };
    }

    // =========================================================================
    // FALLO TOTAL: no hay módulo adecuado
    // =========================================================================
    Logger.error('[ModuleRouter] No se pudo enrutar a ningún módulo.', input);

    return {
      moduleId: null,
      versionId: null,
      resolved: null,
      error: 'No se encontró módulo compatible',
      source: 'fatal',
    };
  }
}

export default ModuleRouter;

/**
 * securityLayer.ts — AURA-MCP (Enterprise 2025)
 * ================================================================================
 * Capa de seguridad y validación profunda del ecosistema AURA-MCP.
 *
 * Basado en:
 *  ✔ Plantilla MCP IA Modular.pdf
 *      - Hardening (CSRF, IP whitelist, metadata)            L6-L15
 *      - Autenticación, JWT, RLS                             L31-L43
 *      - Validación contextual                               L33-L36
 *      - Expiración de resumeURL                             L74-L81
 *
 * Funciones principales:
 *  - Validación de origen y canal
 *  - IP Whitelist
 *  - Validación JWT / RLS
 *  - Validación contextual (usuario, módulo, rol)
 *  - Validación estructural del input
 *  - Validación semántica (según políticas del módulo)
 *  - Validación de resumeURL (TTL + firma)
 */

import crypto from 'crypto';
import jwt from 'jsonwebtoken';
import { Logger } from '../lib/logger.js';

// =============================================================================
// 1. Tipos y config
// =============================================================================

export interface SecurityConfig {
  originsAllowed?: string[];
  ipWhitelist?: string[];
  jwtSecret?: string;
  requireJwt?: boolean;
  enableOriginCheck?: boolean;
  enableIpWhitelist?: boolean;
  enableContextValidation?: boolean;
  enableSemanticValidation?: boolean;

  resumeUrlSignatureSecret?: string;
  resumeUrlTtlMinutes?: number;

  // RLS-aware (para Supabase u otras BD)
  rlsFields?: string[];
}

export interface RequestMeta {
  ip?: string;
  origin?: string;
  userAgent?: string;
  headers?: Record<string, any>;
  user?: any; // usuario autenticado
  context?: any; // contexto del módulo
  timestamp?: number;
}

export interface ValidationResult {
  ok: boolean;
  reason?: string;
  meta?: any;
}

// =============================================================================
// 2. Security Layer principal
// =============================================================================

export class SecurityLayer {
  private static config: SecurityConfig = {
    originsAllowed: ['*'],
    ipWhitelist: [],
    jwtSecret: '',
    requireJwt: false,
    enableOriginCheck: true,
    enableIpWhitelist: false,
    enableContextValidation: true,
    enableSemanticValidation: true,

    resumeUrlSignatureSecret: '',
    resumeUrlTtlMinutes: 60,

    rlsFields: ['user_id', 'rol', 'contexto_modulo'],
  };

  // ---------------------------------------------------------------------------
  // Cargar configuración global
  // ---------------------------------------------------------------------------
  static configure(cfg: Partial<SecurityConfig>) {
    this.config = { ...this.config, ...cfg };
    Logger.info('[SecurityLayer] Configuración cargada', this.config);
  }

  // =============================================================================
  // 3. Validación de origen (anti-CSRF según PDF)
  // =============================================================================
  static checkOrigin(origin?: string): ValidationResult {
    if (!this.config.enableOriginCheck) return { ok: true };

    const allowed = this.config.originsAllowed || [];

    if (allowed.includes('*')) return { ok: true };

    if (!origin) {
      return { ok: false, reason: 'Missing Origin header.' };
    }

    if (!allowed.includes(origin)) {
      return {
        ok: false,
        reason: `Origin not allowed: ${origin}`,
      };
    }

    return { ok: true };
  }

  // =============================================================================
  // 4. Validación IP Whitelist
  // =============================================================================
  static checkIpWhitelist(ip?: string): ValidationResult {
    if (!this.config.enableIpWhitelist) return { ok: true };
    if (!ip) return { ok: false, reason: 'IP no detectada.' };

    const whitelist = this.config.ipWhitelist || [];

    if (whitelist.length === 0) return { ok: true };

    if (!whitelist.includes(ip)) {
      return { ok: false, reason: `IP prohibida: ${ip}` };
    }

    return { ok: true };
  }

  // =============================================================================
  // 5. Validación JWT (Autenticación + claims + RLS)
  // =============================================================================
  static checkJwt(token?: string): ValidationResult {
    const { requireJwt, jwtSecret, rlsFields } = this.config;

    if (!requireJwt) return { ok: true };

    if (!token) {
      return { ok: false, reason: 'JWT requerido pero no recibido.' };
    }

    try {
      const decoded = jwt.verify(token, jwtSecret || '');
      // Validación RLS básica (si el módulo lo requiere)
      if (rlsFields && typeof decoded === 'object') {
        for (const field of rlsFields) {
          if (!(field in decoded)) {
            return {
              ok: false,
              reason: `JWT missing field required for RLS: ${field}`,
            };
          }
        }
      }

      return { ok: true, meta: decoded };
    } catch (err: any) {
      return { ok: false, reason: 'JWT inválido o expirado.' };
    }
  }

  // =============================================================================
  // 6. Validación contextual (PDF: validación doble contextual)
  // =============================================================================
  static checkContext(meta: RequestMeta): ValidationResult {
    if (!this.config.enableContextValidation) return { ok: true };

    const { user, context } = meta;

    if (!user) {
      return { ok: false, reason: 'Contexto inválido: usuario no autenticado.' };
    }

    if (!context) {
      return { ok: false, reason: 'Contexto inválido: falta contexto del módulo.' };
    }

    // Ejemplo: validar que user.context_id == context.context_id
    if (context.context_id && user.context_id && context.context_id !== user.context_id) {
      return {
        ok: false,
        reason: 'Context mismatch entre usuario y módulo.',
      };
    }

    return { ok: true };
  }

  // =============================================================================
  // 7. Validación semántica (PDF: semantic validation)
  // =============================================================================
  static checkSemantic(input: string): ValidationResult {
    if (!this.config.enableSemanticValidation) return { ok: true };

    if (!input || input.length < 1) {
      return { ok: false, reason: 'Input vacío o inválido.' };
    }

    // Anti-spoof / anti-injection básico
    if (/<script>|<img|onerror=/gi.test(input)) {
      return { ok: false, reason: 'Input contiene patrones prohibidos.' };
    }

    return { ok: true };
  }

  // =============================================================================
  // 8. Validación de resumeURL (TTL + firma) — directo del PDF
  // =============================================================================
  static signResumeUrl(sessionId: string): string {
    const secret = this.config.resumeUrlSignatureSecret || 'aura_default_secret';

    const payload = `${sessionId}:${Date.now()}`;
    const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

    const encoded = Buffer.from(`${payload}:${signature}`).toString('base64');
    return encoded;
  }

  static validateResumeUrl(encoded: string): ValidationResult {
    try {
      const secret = this.config.resumeUrlSignatureSecret || 'aura_default_secret';

      const decoded = Buffer.from(encoded, 'base64').toString('utf8');
      const [sessionId, timestampStr, signature] = decoded.split(':');
      const timestamp = parseInt(timestampStr);

      // Verificar firma
      const expectedSig = crypto
        .createHmac('sha256', secret)
        .update(`${sessionId}:${timestamp}`)
        .digest('hex');

      if (signature !== expectedSig) {
        return { ok: false, reason: 'Firma de resumeURL inválida.' };
      }

      // Verificar TTL (PDF: expiración)
      const ttl = (this.config.resumeUrlTtlMinutes || 60) * 60 * 1000;
      if (Date.now() - timestamp > ttl) {
        return { ok: false, reason: 'resumeURL expirado.' };
      }

      return { ok: true, meta: { sessionId } };
    } catch (err: any) {
      return { ok: false, reason: 'resumeURL inválido.' };
    }
  }

  // =============================================================================
  // 9. Validación combinada
  // =============================================================================

  /**
   * Ejecuta TODAS las validaciones de seguridad.
   */
  static validateRequest(input: string, meta: RequestMeta): ValidationResult {
    // Origin
    const originCheck = this.checkOrigin(meta.origin);
    if (!originCheck.ok) return originCheck;

    // IP whitelist
    const ipCheck = this.checkIpWhitelist(meta.ip);
    if (!ipCheck.ok) return ipCheck;

    // JWT
    const jwtToken = meta.headers?.authorization?.replace('Bearer ', '');
    const jwtCheck = this.checkJwt(jwtToken);
    if (!jwtCheck.ok) return jwtCheck;

    // Context
    const contextCheck = this.checkContext({
      user: jwtCheck.meta,
      context: meta.context,
    });
    if (!contextCheck.ok) return contextCheck;

    // Semantic
    const semanticCheck = this.checkSemantic(input);
    if (!semanticCheck.ok) return semanticCheck;

    return { ok: true };
  }
}

export default SecurityLayer;

/**
 * toolRegistry.ts — AURA-MCP
 * ================================================================================
 * Registro centralizado de tools MCP y herramientas internas de AURA.
 *
 * Funciones principales:
 *  ✔ Indexar todas las tools cargadas por MCPToolLoader
 *  ✔ Buscador por nombre, alias, scope y tipo
 *  ✔ Normalización hacia LC_Tool (LangChain format)
 *  ✔ Proveedor unificado para el AURAToolkit
 *  ✔ Cache inteligente y métricas
 *
 * Este módulo permite que:
 *   - LangChainExecutor obtenga tools por nombre
 *   - AURAToolkit entregue el set filtrado al agente
 *   - PipelineEngine consulte herramientas disponibles
 */

import { z } from 'zod';
import { Logger } from '../lib/logger.js';
import MCPToolLoader, { MCPToolContract } from './mcpToolLoader.js';

// ============================================================================
// 1. Tipo normalizado para Tools LangChain
// ============================================================================

export interface NormalizedLCTool {
  name: string;
  description: string;
  run: (input: any) => Promise<any>;
  raw: MCPToolContract;
}

// ============================================================================
// 2. ToolRegistry Core
// ============================================================================

class ToolRegistryCore {
  private tools: Map<string, NormalizedLCTool> = new Map();
  private aliases: Map<string, string> = new Map();

  private isInitialized = false;

  // ==========================================================================
  // Inicialización: carga tools desde MCPToolLoader
  // ==========================================================================
  public async initialize() {
    if (this.isInitialized) return;

    Logger.info('[ToolRegistry] Inicializando ToolRegistry…');

    const loaded = await MCPToolLoader.loadAllTools();

    loaded.forEach((tool) => {
      const normalized = this.normalizeTool(tool);
      this.tools.set(normalized.name, normalized);

      Logger.info('[ToolRegistry] Tool registrada', { name: normalized.name });

      // Registrar alias si el tool tiene nombres secundarios
      // (soportar convención: <scope>.<name>)
      const alias1 = `mcp.${normalized.name}`;
      const alias2 = `tool.${normalized.name}`;

      this.aliases.set(alias1, normalized.name);
      this.aliases.set(alias2, normalized.name);
    });

    this.isInitialized = true;

    Logger.info('[ToolRegistry] Inicializado exitosamente', {
      total: this.tools.size,
    });
  }

  // ==========================================================================
  // Normalización de tool hacia formato LangChain (LC_Tool)
  // ==========================================================================
  private normalizeTool(tool: MCPToolContract): NormalizedLCTool {
    return {
      name: tool.name,
      description: tool.description,
      raw: tool,

      // wrapper que ejecuta el MCP Tool
      run: async (input: any) => {
        try {
          const parsedInput = tool.inputSchema.parse(input);
          const output = await tool.execute(parsedInput, {});

          // Validar el output con el outputSchema
          const validated = tool.outputSchema.parse(output);
          return validated;
        } catch (err: any) {
          Logger.error('[ToolRegistry] Error ejecutando tool', {
            tool: tool.name,
            error: err.message,
          });

          throw new Error(`Tool ${tool.name} failed: ${err.message}`);
        }
      },
    };
  }

  // ==========================================================================
  // Accesos públicos
  // ==========================================================================

  /**
   * Devuelve una tool si existe exacta.
   */
  public get(name: string): NormalizedLCTool | undefined {
    const resolved = this.aliases.get(name) || name;
    return this.tools.get(resolved);
  }

  /**
   * Busca tools cuyo nombre empiece con string.
   */
  public search(prefix: string): NormalizedLCTool[] {
    const results: NormalizedLCTool[] = [];

    for (const t of this.tools.values()) {
      if (t.name.startsWith(prefix)) {
        results.push(t);
      }
    }

    return results;
  }

  /**
   * Devuelve todas las tools como LC_Tool para LangChain.
   */
  public getAllAsLangChainTools() {
    return [...this.tools.values()].map((t) => ({
      name: t.name,
      description: t.description,
      func: async (input: any) => t.run(input),
    }));
  }

  /**
   * Devuelve todas las tools brutas MCP.
   */
  public listRaw(): MCPToolContract[] {
    return [...this.tools.values()].map((t) => t.raw);
  }

  /**
   * Recarga herramientas dinámicamente (hot reload).
   */
  public async reload() {
    Logger.warn('[ToolRegistry] Hot Reload iniciado…');

    this.tools.clear();
    this.aliases.clear();
    this.isInitialized = false;

    await this.initialize();

    Logger.warn('[ToolRegistry] Hot Reload completo');

    return true;
  }

  /**
   * Snapshot útil para diagnosticar/debuggear.
   */
  public snapshot() {
    return [...this.tools.values()].map((t) => ({
      name: t.name,
      description: t.description,
    }));
  }
}

// ============================================================================
// 3. Export como Singleton
// ============================================================================

export const ToolRegistry = new ToolRegistryCore();

export default ToolRegistry;

/**
 * uiJsonEngine.ts — AURA-MCP
 * ================================================================================
 * Motor UI JSON-Driven del ecosistema AURA-MCP.
 *
 * Basado directamente en la sección “JSON-driven UI & content_blocks”
 * de la Plantilla Maestra MCP+IA.
 *
 * Funciones principales:
 *   ✔ Generar pantallas dinámicas según módulo
 *   ✔ Unir (merge) diferentes content_blocks
 *   ✔ Validar estructura UI (según blueprint)
 *   ✔ Permitir UI generada por IA (autoLayout)
 *   ✔ Adjuntar metadata, acciones y resume_url
 *
 * Alineado con:
 *   - Plantilla Mcp Ia Modular.pdf
 *       • content_blocks (L18-L81)
 *       • reglas de UI JSON-driven (L21-L31)
 */

import { Logger } from '../lib/logger.js';
import { McpModuleBlueprint, McpModuleBlueprintSchema } from './mcpModuleBlueprint.js';

// ============================================================================
// 1. Tipos UI estándar (extraídos del PDF)
// ============================================================================

export type UIContentBlock =
  | {
      type: 'text';
      content: string;
      style?: string;
    }
  | {
      type: 'input';
      id: string;
      label: string;
      input_type: string; // text, number, email, textarea
      placeholder?: string;
      required?: boolean;
      value?: any;
    }
  | {
      type: 'button';
      id: string;
      label: string;
      action: string; // acción que activará el módulo/AI
      style?: string;
    }
  | {
      type: 'file_upload';
      id: string;
      label: string;
      accept: string[]; // ej: ["pdf", "jpg"]
      max_files?: number;
    }
  | {
      type: 'select';
      id: string;
      label: string;
      options: { label: string; value: string }[];
      placeholder?: string;
      required?: boolean;
      value?: string;
    }
  | {
      type: 'container';
      blocks: UIContentBlock[];
      style?: string;
    };

// Respuesta UI completa
export interface UIResponse {
  screen_title: string;
  subtitle?: string;
  content_blocks: UIContentBlock[];
  theme?: string;
  resume_url?: string | null;
  metadata?: Record<string, any>;
}

// ============================================================================
// 2. Motor principal
// ============================================================================

export class UIJsonEngine {
  /**
   * Genera una UI desde un blueprint de módulo MCP.
   * Usa:
   *   blueprint.architecture.uiResponseContract
   */
  static fromBlueprint(blueprint: McpModuleBlueprint): UIResponse | null {
    try {
      const contract = blueprint.architecture.uiResponseContract;

      if (!contract) {
        Logger.warn('[UIJsonEngine] El módulo no define interfaz UI');
        return null;
      }

      // Validación ligera
      if (!Array.isArray(contract.content_blocks)) {
        Logger.error('[UIJsonEngine] content_blocks inválidos');
        return null;
      }

      return {
        screen_title: contract.screen_title,
        subtitle: contract.subtitle,
        theme: contract.theme,
        content_blocks: contract.content_blocks,
        resume_url: contract.resume_url || null,
        metadata: contract.metadata || {},
      };
    } catch (err: any) {
      Logger.error('[UIJsonEngine] Error generando UI', {
        error: err.message,
      });
      return null;
    }
  }

  /**
   * Genera UI dinámica desde texto + IA (autoLayout).
   * AURA interpreta el contenido del usuario y construye pantallas.
   */
  static async fromAi(title: string, text: string, context: any = {}): Promise<UIResponse> {
    Logger.info('[UIJsonEngine] Generando UI autoLayout con IA...');

    // prompt simple (en producción usarías systemPrompt + AURA_TOOLKIT)
    const generated = await global.AURA_MODEL.invoke({
      model: 'gpt-4o-mini',
      prompt: `
        Eres el motor UI de AURA.
        Convierte este texto en content_blocks JSON coherentes.

        Texto:
        ${text}

        Devuelve sólo JSON, sin explicaciones.
      `,
    });

    let blocks: UIContentBlock[] = [];
    try {
      blocks = JSON.parse(generated).content_blocks;
    } catch {
      blocks = [
        {
          type: 'text',
          content: text,
        },
      ];
    }

    return {
      screen_title: title,
      content_blocks: blocks,
      metadata: { source: 'ai-generated', context },
    };
  }

  /**
   * Fusión (merge) de dos respuestas UI.
   * Útil cuando un agente produce parte de la UI y otro agente agrega bloques.
   */
  static merge(uiA: UIResponse, uiB: UIResponse): UIResponse {
    return {
      ...uiA,
      content_blocks: [...uiA.content_blocks, ...uiB.content_blocks],
      metadata: {
        ...(uiA.metadata || {}),
        ...(uiB.metadata || {}),
      },
      resume_url: uiB.resume_url || uiA.resume_url || null,
    };
  }

  /**
   * Composición avanzada:
   *   UI(CONTAINER) ← BLOCKS
   */
  static wrapInContainer(title: string, blocks: UIContentBlock[], style: string = ''): UIResponse {
    return {
      screen_title: title,
      content_blocks: [
        {
          type: 'container',
          style,
          blocks,
        },
      ],
    };
  }

  /**
   * Inserta un bloque en una posición específica.
   */
  static insertBlock(ui: UIResponse, block: UIContentBlock, index: number): UIResponse {
    const newBlocks = [...ui.content_blocks];
    newBlocks.splice(index, 0, block);

    return {
      ...ui,
      content_blocks: newBlocks,
    };
  }

  /**
   * Reemplaza un bloque según ID.
   */
  static replaceBlock(ui: UIResponse, blockId: string, newBlock: UIContentBlock): UIResponse {
    return {
      ...ui,
      content_blocks: ui.content_blocks.map((b: any) => (b.id === blockId ? newBlock : b)),
    };
  }

  /**
   * Adjunta o reemplaza resume_url.
   */
  static attachResumeUrl(ui: UIResponse, resumeUrl: string): UIResponse {
    return {
      ...ui,
      resume_url: resumeUrl,
    };
  }

  /**
   * Validación superficial de UI para debug.
   */
  static validate(ui: UIResponse): boolean {
    if (!ui.screen_title) return false;
    if (!Array.isArray(ui.content_blocks)) return false;
    return true;
  }
}

export default UIJsonEngine;

/**
 * n8nFlowBlueprint.ts — AURA-MCP
 * ================================================================================
 * Capa estándar de integración con n8n para módulos MCP+IA.
 *
 * Objetivos:
 *  - Representar en código el patrón de flujo MCP descrito en la Plantilla MCP+IA:
 *      • Webhook de entrada
 *      • Validación / Normalización
 *      • Wait node (resumeURL)
 *      • AI Agent (AURA / LLM)
 *      • Vector DB (RAG)
 *      • Respond to Webhook (UI JSON-driven)
 *
 *  - Permitir:
 *      ✔ Definir blueprints de flujos n8n de forma tipada
 *      ✔ Validar estructuras antes de desplegar
 *      ✔ Generar flujos estándar MCP de manera programática
 *
 * Alineado con:
 *  - Plantilla Mcp Ia Modular (arquitectura funcional + nodos n8n)
 */

import { z } from 'zod';
import { Logger } from '../src/lib/logger.js';

// ============================================================================
// 1. ENUMS Y TIPOS BASE
// ============================================================================

export const N8nNodeTypeEnum = z.enum([
  'webhook',
  'wait',
  'aiAgent',
  'promptGenerator',
  'vectorDb',
  'httpRequest',
  'set',
  'function',
  'respondWebhook',
  'decision',
  'subworkflow',
  'unknown',
]);

export type N8nNodeType = z.infer<typeof N8nNodeTypeEnum>;

export const N8nEdgeTypeEnum = z.enum(['main', 'error', 'conditional']);
export type N8nEdgeType = z.infer<typeof N8nEdgeTypeEnum>;

export const N8nPositionSchema = z.object({
  x: z.number(),
  y: z.number(),
});

// ============================================================================
// 2. NODOS Y ARISTAS (ESCUELA N8N)
// ============================================================================

export const N8nNodeSchema = z.object({
  id: z
    .string()
    .min(1)
    .regex(/^[a-zA-Z0-9_-]+$/, 'El id del nodo debe ser alfanumérico.'),
  name: z.string().min(1),
  type: N8nNodeTypeEnum,
  position: N8nPositionSchema.optional(),
  description: z.string().optional(),
  critical: z.boolean().default(false),
  tags: z.array(z.string()).default([]),

  // Configuración específica del nodo (n8n JSON)
  config: z.record(z.any()).default({}),
});

export type N8nNode = z.infer<typeof N8nNodeSchema>;

export const N8nEdgeSchema = z.object({
  id: z
    .string()
    .min(1)
    .regex(/^[a-zA-Z0-9_-]+$/, 'El id de la arista debe ser alfanumérico.'),
  source: z.string().min(1),
  target: z.string().min(1),
  type: N8nEdgeTypeEnum.default('main'),
  condition: z.string().optional(),
});

export type N8nEdge = z.infer<typeof N8nEdgeSchema>;

// ============================================================================
// 3. BLUEPRINT COMPLETO DE FLUJO N8N
// ============================================================================

export const N8nFlowBlueprintSchema = z.object({
  id: z
    .string()
    .min(1)
    .regex(/^[a-zA-Z0-9_-]+$/, 'El id del flujo debe ser alfanumérico.'),
  name: z.string().min(3),
  description: z.string().min(10),

  // módulo MCP+IA asociado (opcional)
  moduleId: z.string().optional(),

  // entorno (dev/staging/prod, etc.)
  envMode: z.string().default('local'),

  // nodos y enlaces
  nodes: z.array(N8nNodeSchema),
  edges: z.array(N8nEdgeSchema),

  // metadata extra (para router, UI, etc.)
  metadata: z
    .object({
      tags: z.array(z.string()).default([]),
      version: z.string().default('v1'),
      resumeUrlEnabled: z.boolean().default(true),
      // nombre del nodo que expone la resume_url (normalmente el Wait)
      resumeNodeId: z.string().optional(),
      // canal asociado (web, mobile, api, discord…)
      channels: z.array(z.string()).default([]),
    })
    .default({
      tags: [],
      version: 'v1',
      resumeUrlEnabled: true,
      channels: [],
    }),
});

export type N8nFlowBlueprint = z.infer<typeof N8nFlowBlueprintSchema>;

// ============================================================================
// 4. FACTORY — FLUJO MCP ESTÁNDAR
// ============================================================================

/**
 * Crea un flujo estándar MCP+IA:
 *
 *   Webhook → (Set/Function) → Wait → AI Agent → Vector DB → Respond to Webhook
 *
 * Patrón recomendado en la plantilla:
 *   - Webhook recibe evento JSON.
 *   - Nodo de normalización/validación.
 *   - Nodo Wait expone resume_url.
 *   - AI Agent consulta contexto + RAG.
 *   - Vector DB consulta embeddings y aporta evidencias.
 *   - Respond to Webhook devuelve UI JSON-driven al cliente.
 */
export function createStandardMcpFlowBlueprint(params: {
  id: string;
  name: string;
  description: string;
  moduleId?: string;
  basePath?: string; // ruta HTTP para el webhook (ej: /api/mcp/onboarding)
  envMode?: string;
}): N8nFlowBlueprint {
  const {
    id,
    name,
    description,
    moduleId,
    basePath = '/webhook/mcp/default',
    envMode = 'local',
  } = params;

  const nodes: N8nNode[] = [
    {
      id: 'webhook_in',
      name: 'Entrada Webhook',
      type: 'webhook',
      description: 'Recibe el evento HTTP entrante para el módulo MCP.',
      critical: true,
      config: {
        path: basePath,
        method: 'POST',
        responseMode: 'onReceived',
      },
      tags: [],
    },
    {
      id: 'normalize_input',
      name: 'Normalizar / Validar Input',
      type: 'function',
      description: 'Limpia y normaliza el payload para que cumpla con InputSchema estándar.',
      critical: true,
      config: {
        fn: 'normalizeInputToMcpStandard',
      },
      tags: [],
    },
    {
      id: 'wait_resume',
      name: 'Wait (resumeURL)',
      type: 'wait',
      description:
        'Pausa el flujo y expone una resume_url para reanudar desde el cliente o desde otro sistema.',
      critical: true,
      config: {
        waitType: 'webhook',
        ttlMinutes: 60,
      },
      tags: [],
    },
    {
      id: 'prompt_generator',
      name: 'Prompt Generator',
      type: 'promptGenerator',
      description: 'Construye el prompt base para el agente IA según el módulo y el contexto.',
      config: {
        moduleId,
      },
      critical: false,
      tags: [],
    },
    {
      id: 'ai_agent',
      name: 'AI Agent (AURA)',
      type: 'aiAgent',
      description: 'Agente IA que consume el prompt, contexto y RAG para producir respuesta.',
      critical: true,
      config: {
        agent: 'orchestrator_core',
        useRag: true,
      },
      tags: [],
    },
    {
      id: 'vector_db',
      name: 'Vector DB (RAG)',
      type: 'vectorDb',
      description: 'Consulta embeddings en Supabase / vector engine y devuelve evidencias.',
      config: {
        table: 'documents_embeddings',
        topK: 8,
      },
      critical: false,
      tags: [],
    },
    {
      id: 'respond_webhook',
      name: 'Responder Webhook',
      type: 'respondWebhook',
      description: 'Devuelve una UI JSON-driven al cliente (content_blocks + resume_url).',
      critical: true,
      config: {
        contentType: 'application/json',
      },
      tags: [],
    },
  ];

  const edges: N8nEdge[] = [
    {
      id: 'webhook_to_normalize',
      source: 'webhook_in',
      target: 'normalize_input',
      type: 'main',
    },
    {
      id: 'normalize_to_wait',
      source: 'normalize_input',
      target: 'wait_resume',
      type: 'main',
    },
    {
      id: 'wait_to_prompt',
      source: 'wait_resume',
      target: 'prompt_generator',
      type: 'main',
    },
    {
      id: 'prompt_to_ai',
      source: 'prompt_generator',
      target: 'ai_agent',
      type: 'main',
    },
    {
      id: 'ai_to_vector',
      source: 'ai_agent',
      target: 'vector_db',
      type: 'main',
    },
    {
      id: 'vector_to_respond',
      source: 'vector_db',
      target: 'respond_webhook',
      type: 'main',
    },
  ];

  const blueprint: N8nFlowBlueprint = {
    id,
    name,
    description,
    moduleId,
    envMode,
    nodes,
    edges,
    metadata: {
      tags: ['mcp', 'aura', 'standard_flow'],
      version: 'v1',
      resumeUrlEnabled: true,
      resumeNodeId: 'wait_resume',
      channels: ['api', 'web'],
    },
  };

  // Validación con Zod antes de devolver
  return N8nFlowBlueprintSchema.parse(blueprint);
}

// ============================================================================
// 5. VALIDACIÓN Y HELPERS
// ============================================================================

export function validateN8nFlowBlueprint(data: any): N8nFlowBlueprint {
  return N8nFlowBlueprintSchema.parse(data);
}

export const N8nFlowBlueprintFactory = {
  /**
   * Crea un blueprint vacío para ser completado manualmente.
   */
  createEmpty(id: string, name: string, description: string): N8nFlowBlueprint {
    const blueprint: N8nFlowBlueprint = {
      id,
      name,
      description,
      envMode: 'local',
      nodes: [],
      edges: [],
      metadata: {
        tags: [],
        version: 'v1',
        resumeUrlEnabled: false,
        channels: [],
      },
    };

    return N8nFlowBlueprintSchema.parse(blueprint);
  },

  /**
   * Crea un blueprint estándar MCP usando la factory superior.
   */
  createStandard(params: {
    id: string;
    name: string;
    description: string;
    moduleId?: string;
    basePath?: string;
    envMode?: string;
  }): N8nFlowBlueprint {
    return createStandardMcpFlowBlueprint(params);
  },
};

export default N8nFlowBlueprintSchema;

/**
 * vectorEngine.ts — AURA-MCP
 * ================================================================================
 * Motor vectorial (RAG Engine) para embeddings, similitud y recuperación semántica.
 *
 *  ✔ Crea embeddings
 *  ✔ Inserta en tabla vectorial
 *  ✔ match_embeddings() → recuperación top-K
 *  ✔ RAG híbrido (texto + metadata)
 *
 * Alineado con:
 *    Plantilla MCP IA Modular (sección Vector DB, match_embeddings)
 */

import { Logger } from '../lib/logger.js';
import SupabaseConnector from './supabaseConnector.js';

export interface EmbeddingResult {
  text: string;
  embedding: number[];
  metadata?: Record<string, any>;
}

export interface RagMatch {
  id: string;
  text: string;
  score: number;
  metadata: Record<string, any>;
}

export interface VectorConfig {
  table: string; // ej: "documents_embeddings"
  textColumn: string; // ej: "content"
  embedColumn: string; // ej: "embedding"
  metadataColumn?: string;
}

class VectorEngineCore {
  private config: VectorConfig | null = null;

  configure(cfg: VectorConfig) {
    this.config = cfg;
    Logger.info('[VectorEngine] Configurado', cfg);
  }

  // ============================================================================
  // EMBEDDINGS
  // ============================================================================

  async embedText(text: string): Promise<number[]> {
    const model = global.AURA_MODEL;
    const result = await model.invoke({
      model: 'text-embedding-3-large',
      prompt: text,
    });

    if (!result.embedding) {
      throw new Error('[VectorEngine] Modelo no devolvió embedding.');
    }

    return result.embedding;
  }

  // ============================================================================
  // INSERTAR EN TABLA VECTORIAL
  // ============================================================================

  async insertEmbedding(result: EmbeddingResult) {
    if (!this.config) throw new Error('VectorEngine sin configuración.');

    const client = SupabaseConnector.getClient();
    const cfg = this.config;

    const row: any = {
      [cfg.textColumn]: result.text,
      [cfg.embedColumn]: result.embedding,
      ...(cfg.metadataColumn ? { [cfg.metadataColumn]: result.metadata || {} } : {}),
    };

    const { error } = await client.from(cfg.table).insert(row);

    if (error) {
      Logger.error('[VectorEngine] Error insertEmbedding:', {
        error: error.message,
      });
      return false;
    }

    return true;
  }

  // ============================================================================
  // match_embeddings() — RAG
  // ============================================================================

  async matchEmbedding(query: string, topK: number = 5): Promise<RagMatch[]> {
    if (!this.config) throw new Error('VectorEngine sin configuración.');
    const cfg = this.config;

    // 1) Embedding del query
    const queryEmb = await this.embedText(query);

    // 2) Consulta a Supabase usando match_embeddings()
    const client = SupabaseConnector.getClient();

    const { data, error } = await client.rpc('match_embeddings', {
      query_embedding: queryEmb,
      match_count: topK,
    });

    if (error) {
      Logger.error('[VectorEngine] Error en match_embeddings RPC:', {
        error: error.message,
      });
      return [];
    }

    // 3) Formateo de respuesta
    return (data || []).map((row: any) => ({
      id: row.id,
      text: row.content,
      score: row.score,
      metadata: row.metadata || {},
    }));
  }

  // ============================================================================
  // RAG COMPLETO: Embeddings + matches + síntesis
  // ============================================================================

  async rag(query: string, topK: number = 5) {
    const matches = await this.matchEmbedding(query, topK);

    const context = matches
      .map(
        (m) =>
          `---\nID: ${m.id}\nScore: ${m.score}\nMetadata: ${JSON.stringify(m.metadata)}\n${m.text}`
      )
      .join('\n\n');

    return {
      query,
      matches,
      context,
    };
  }
}

export const VectorEngine = new VectorEngineCore();
export default VectorEngine;

/**
 * langchainExecutor.ts — AURA-MCP
 * ==============================================================================
 * Ejecuta agentes AURA sobre el motor de lenguaje configurado (global.AURA_MODEL)
 * con soporte para:
 *
 *  ✔ Tools dinámicas (ToolRegistry + AURAToolkit)
 *  ✔ Validación de agentes con AgentSchemas
 *  ✔ Integración directa con PipelineEngine (etapa primaria)
 *  ✔ Registro de trazas (traceId, modelo, tools, latencia)
 *
 * Diseñado para trabajar con:
 *   - PipelineEngine.run()
 *   - AgentManager
 *   - AURAToolkit
 *   - ToolRegistry
 */

import { Logger } from './lib/logger.js';
import { Metrics } from './lib/metrics.js';
import { Config } from './lib/config.js';

import { AgentManager } from './agentManager.js';
import { AURAToolkit } from './core/auraToolkit.js';
import { ToolRegistry } from './core/toolRegistry.js';

import { validateAgentDefinition } from './core/agentSchemas.js';

import type { AgentDefinition } from './types/interfaces.js';

// ============================================================================
// 1. Tipos internos
// ============================================================================

interface RunOptions {
  agentName: string;
  input: string;
  context?: any;
}

interface ModelPayload {
  model: string;
  temperature: number;
  systemPrompt: string;
  input: string;
  context: any;
  tools: {
    name: string;
    description: string;
    func: (args: any) => Promise<any>;
  }[];
  agentMeta: {
    name: string;
    role: string;
  };
}

// ============================================================================
// 2. Utilidades internas
// ============================================================================

function createTraceId(): string {
  const now = Date.now().toString(16);
  const rand = Math.floor(Math.random() * 1e8).toString(16);
  return `trace_${now}_${rand}`;
}

function getAuraModel() {
  const model = (globalThis as any).AURA_MODEL;
  if (!model || typeof model.invoke !== 'function') {
    throw new Error(
      '[LangChainExecutor] global.AURA_MODEL no está configurado o no expone invoke().'
    );
  }
  return model;
}

// ============================================================================
// 3. LangChainExecutor — Clase principal
// ============================================================================

export class LangChainExecutor {
  /**
   * Ejecuta un agente AURA usando el modelo configurado.
   *
   * Usado por:
   *  - PipelineEngine (etapa primaria y backups por rol)
   *  - Cualquier llamada directa desde el Core
   */
  static async runAgent(agentName: string, input: string, context: any = {}): Promise<any> {
    const traceId = createTraceId();
    const startedAt = Date.now();

    Logger.info('[LangChainExecutor] Iniciando ejecución de agente', {
      traceId,
      agent: agentName,
      preview: input.slice(0, 200),
    });

    Metrics.countAgentCall?.(agentName);

    // --------------------------------------------------------------
    // 1. Resolver y validar agente
    // --------------------------------------------------------------
    const storedAgent = AgentManager.get(agentName) as AgentDefinition | undefined;

    if (!storedAgent) {
      Logger.error('[LangChainExecutor] Agente no encontrado', {
        traceId,
        agent: agentName,
      });
      throw new Error(`Agente no registrado: ${agentName}`);
    }

    const agent = validateAgentDefinition(storedAgent);

    // --------------------------------------------------------------
    // 2. Inicializar ToolRegistry y obtener tools dinámicas
    // --------------------------------------------------------------
    await ToolRegistry.initialize();

    const tools = await AURAToolkit.getTools(agent);

    Logger.info('[LangChainExecutor] Tools asignadas al agente', {
      traceId,
      agent: agent.name,
      tools: tools.map((t) => t.name),
    });

    // --------------------------------------------------------------
    // 3. Preparar payload para el modelo
    // --------------------------------------------------------------
    const modelName =
      (Config.primaryModel as string) || (Config.fallbackModel as string) || 'gpt-4o-mini';

    const temperature = typeof agent.temperature === 'number' ? agent.temperature : 0.2;

    const payload: ModelPayload = {
      model: modelName,
      temperature,
      systemPrompt: agent.systemPrompt,
      input,
      context: {
        ...context,
        agent: {
          name: agent.name,
          role: agent.role,
          memory: agent.memory || {},
        },
      },
      tools: tools.map((t) => ({
        name: t.name,
        description: t.description,
        func: async (args: any) => t.func(args),
      })),
      agentMeta: {
        name: agent.name,
        role: agent.role,
      },
    };

    const auraModel = getAuraModel();

    // --------------------------------------------------------------
    // 4. Invocar modelo con soporte de tools
    // --------------------------------------------------------------
    try {
      const result = await auraModel.invoke(payload);

      const durationMs = Date.now() - startedAt;
      Metrics.countAgentSuccess?.(agentName);

      Logger.info('[LangChainExecutor] Ejecución completada', {
        traceId,
        agent: agent.name,
        model: modelName,
        durationMs,
      });

      // Registrar traza opcionalmente en un subsistema global
      try {
        const tracer = (globalThis as any).AURA_TRACE;
        if (tracer && typeof tracer.capture === 'function') {
          tracer.capture({
            traceId,
            agent: agent.name,
            role: agent.role,
            model: modelName,
            durationMs,
            tools: tools.map((t) => t.name),
            inputPreview: input.slice(0, 300),
          });
        }
      } catch {
        // Si falla el sistema de trazas, no rompemos la ejecución
      }

      return result;
    } catch (err: any) {
      const durationMs = Date.now() - startedAt;
      Metrics.countAgentError?.(agentName);

      Logger.error('[LangChainExecutor] Error ejecutando agente', {
        traceId,
        agent: agent.name,
        model: modelName,
        durationMs,
        error: err.message,
      });

      throw err;
    }
  }

  /**
   * Ejecuta un agente pasando ya el AgentDefinition (útil para testing
   * o agentes generados on-the-fly sin usar AgentManager).
   */
  static async runWithDefinition(
    agent: AgentDefinition,
    input: string,
    context: any = {}
  ): Promise<any> {
    const validated = validateAgentDefinition(agent);
    const traceId = createTraceId();
    const startedAt = Date.now();

    await ToolRegistry.initialize();
    const tools = await AURAToolkit.getTools(validated);

    const modelName =
      (Config.primaryModel as string) || (Config.fallbackModel as string) || 'gpt-4o-mini';

    const temperature = typeof validated.temperature === 'number' ? validated.temperature : 0.2;

    const payload: ModelPayload = {
      model: modelName,
      temperature,
      systemPrompt: validated.systemPrompt,
      input,
      context: {
        ...context,
        agent: {
          name: validated.name,
          role: validated.role,
          memory: validated.memory || {},
        },
      },
      tools: tools.map((t) => ({
        name: t.name,
        description: t.description,
        func: async (args: any) => t.func(args),
      })),
      agentMeta: {
        name: validated.name,
        role: validated.role,
      },
    };

    const auraModel = getAuraModel();

    try {
      const result = await auraModel.invoke(payload);
      const durationMs = Date.now() - startedAt;

      Logger.info('[LangChainExecutor] runWithDefinition ok', {
        traceId,
        agent: validated.name,
        model: modelName,
        durationMs,
      });

      return result;
    } catch (err: any) {
      const durationMs = Date.now() - startedAt;

      Logger.error('[LangChainExecutor] runWithDefinition error', {
        traceId,
        agent: validated.name,
        model: modelName,
        durationMs,
        error: err.message,
      });

      throw err;
    }
  }
}

