/**
 * IMPORT: funciones para manejar archivos MCP (importar/monitorizar).
 * - importMcpFile: valida mínima estructura y copia a carpeta mcp_imported del proyecto.
 * - watchMcpFolder: observa carpeta para nuevos .mcp.json y emite evento 'mcp:imported'.
 */

// Carpeta por defecto dentro del proyecto para MCP importados
const DEFAULT_MCP_FOLDER = process.env.MCP_IMPORTED_DIR ?? path.join(process.cwd(), 'mcp_imported');

/**
 * Validación ligera de un objeto MCP (presencia de campos clave).
 */
function isValidMcpPayload(obj: any): boolean {
	if (!obj || typeof obj !== 'object') return false;
	if (!obj.schemaVersion) return false;
	if (!obj.metadata || !obj.metadata.title) return false;
	if (!obj.content || typeof obj.content.cleaned !== 'string') return false;
	return true;
}

/**
 * Importa un archivo MCP JSON al proyecto:
 * - valida estructura mínima
 * - copia a carpeta mcp_imported con timestamp
 * - emite AgentEvents 'mcp:imported'
 * - retorna la ruta destino
 */
export async function importMcpFile(srcPath: string, destFolder: string = DEFAULT_MCP_FOLDER): Promise<string> {
	const absSrc = path.isAbsolute(srcPath) ? srcPath : path.resolve(process.cwd(), srcPath);
	try {
		const raw = await fs.readFile(absSrc, 'utf-8');
		const data = JSON.parse(raw);

		if (!isValidMcpPayload(data)) {
			Logger.warn('agentPromptInjector.importMcpFile.invalid_schema', { srcPath });
			throw new Error('MCP inválido: faltan campos requeridos (schemaVersion/metadata/content)');
		}

		await fs.mkdir(destFolder, { recursive: true });

		const baseName = path.basename(srcPath, path.extname(srcPath));
		const destName = `${baseName}.${Date.now()}.mcp.json`;
		const destPath = path.join(destFolder, destName);

		await fs.writeFile(destPath, JSON.stringify(data, null, 2), 'utf-8');

		// Emitir evento para que UI / Orchestrator lo indexe
		const correlationId = (Logger as any).getCorrelationId ? (Logger as any).getCorrelationId() : undefined;
		const payload = {
			path: destPath,
			metadata: data.metadata,
			importedAt: new Date().toISOString(),
			correlationId: correlationId ?? undefined,
		};
		AgentEvents.emit('mcp:imported', payload);
		Logger.info('agentPromptInjector.importMcpFile.success', { srcPath, destPath });

		return destPath;
	} catch (err) {
		Logger.error('agentPromptInjector.importMcpFile.error', { srcPath, error: (err as Error).message });
		throw err;
	}
}

/**
 * Observa una carpeta por nuevos archivos .mcp.json y los importa automáticamente.
 * Retorna una función para detener el watcher.
 */
export function watchMcpFolder(folder: string = DEFAULT_MCP_FOLDER): () => void {
	const absFolder = path.isAbsolute(folder) ? folder : path.resolve(process.cwd(), folder);

	(async () => {
		try {
			await fs.mkdir(absFolder, { recursive: true });
		} catch {
			/* ignore */
		}
	})();

	try {
		const watcher = chokidar.watch(absFolder, {
			ignored: /(^|[/\\])\../,
			persistent: true,
			awaitWriteFinish: { stabilityThreshold: 500, pollInterval: 100 },
		});

		const onAdd = async (filePath: string) => {
			if (filePath.endsWith('.mcp.json')) {
				try {
					await importMcpFile(filePath, absFolder);
				} catch (e) {
					// ya logueado en importMcpFile
				}
			}
		};

		watcher.on('add', onAdd);

		Logger.info('agentPromptInjector.watchMcpFolder.started', { folder: absFolder });

		return () => {
			watcher.off('add', onAdd);
			watcher.close();
			Logger.info('agentPromptInjector.watchMcpFolder.stopped', { folder: absFolder });
		};
	} catch (err) {
		Logger.error('agentPromptInjector.watchMcpFolder.error', { folder: absFolder, error: (err as Error).message });
		return () => {};
	}
}

import jwt from 'jsonwebtoken';

import { Logger } from './logger.js';

export interface AuthToken {
  agentId: string;
  scope: string[];
  role?: string;
  iat: number;
  exp?: number;
  jti?: string;
}

export interface AuthOptions {
  secret?: string;
  expiresIn?: string | number;
  issuer?: string;
  audience?: string;
  minSecretLength?: number;
}

export class AuthService {
  private secret: string;

  private expiresIn: string | number;

  private issuer: string;

  private audience?: string;

  private revokedTokens: Set<string> = new Set();

  private failedAttempts: Map<string, { count: number; timestamp: number }> = new Map();

  private readonly maxFailedAttempts = 5;

  private readonly failureWindowMs = 15 * 60 * 1000;

  constructor(opts?: AuthOptions) {
    this.secret = opts?.secret ?? process.env.JWT_SECRET ?? '';
    const minLen = opts?.minSecretLength ?? 32;

    if (!this.secret) {
      throw new Error('JWT_SECRET no configurado en env o opciones');
    }

    if (this.secret.length < minLen) {
      Logger.warn('auth.weak_secret', { minLength: minLen, actualLength: this.secret.length });
    }

    this.expiresIn = opts?.expiresIn ?? '24h';
    this.issuer = opts?.issuer ?? 'aura-mcp-core';
    this.audience = opts?.audience ?? process.env.JWT_AUDIENCE;
  }

  // Generar token JWT con jti (JWT ID) para auditoría
  generateToken(agentId: string, scope: string[], role?: string): string {
    try {
      const jti = `${agentId}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
      const payload: AuthToken = {
        agentId,
        scope,
        role: role ?? 'user',
        iat: Math.floor(Date.now() / 1000),
        jti,
      };

      const opts: any = {
        expiresIn: this.expiresIn,
        issuer: this.issuer,
        subject: agentId,
        jwtid: jti,
      };

      if (this.audience) opts.audience = this.audience;

      const token = jwt.sign(payload, this.secret, opts);
      Logger.info('auth.token.generated', { agentId, scope, role, jti });
      return token;
    } catch (err) {
      Logger.error('auth.token.generate_failed', { agentId, error: (err as Error).message });
      throw err;
    }
  }

  // Verificar y parsear token JWT con validación de revocación
  verifyToken(token: string): AuthToken {
    try {
      const opts: any = {
        issuer: this.issuer,
      };
      if (this.audience) opts.audience = this.audience;

      const decoded = jwt.verify(token, this.secret, opts) as unknown as AuthToken;

      // Verificar si el token fue revocado
      if (decoded.jti && this.revokedTokens.has(decoded.jti)) {
        Logger.warn('auth.token.revoked', { jti: decoded.jti, agentId: decoded.agentId });
        throw new Error('Token revocado');
      }

      return decoded;
    } catch (err) {
      // registrar intento fallido para rate limiting
      const agentId = (jwt.decode(token) as any)?.agentId ?? 'unknown';
      this.recordFailedAttempt(agentId);
      Logger.warn('auth.token.verify_failed', { error: (err as Error).message, agentId });
      throw new Error(`Token inválido: ${(err as Error).message}`);
    }
  }

  // Revocar un token (por jti)
  revokeToken(token: string): void {
    try {
      const decoded = jwt.decode(token) as AuthToken;
      if (decoded?.jti) {
        this.revokedTokens.add(decoded.jti);
        Logger.info('auth.token.revoked_explicit', { jti: decoded.jti, agentId: decoded.agentId });
      }
    } catch {
      // ignore decode errors
    }
  }

  // Verificar si un agente está siendo bloqueado por rate limiting
  isBlocked(agentId: string): boolean {
    const record = this.failedAttempts.get(agentId);
    if (!record) return false;

    const elapsed = Date.now() - record.timestamp;
    if (elapsed > this.failureWindowMs) {
      this.failedAttempts.delete(agentId);
      return false;
    }

    return record.count >= this.maxFailedAttempts;
  }

  // Registrar intento fallido
  private recordFailedAttempt(agentId: string): void {
    const record = this.failedAttempts.get(agentId);
    if (!record) {
      this.failedAttempts.set(agentId, { count: 1, timestamp: Date.now() });
    } else {
      const elapsed = Date.now() - record.timestamp;
      if (elapsed > this.failureWindowMs) {
        this.failedAttempts.set(agentId, { count: 1, timestamp: Date.now() });
      } else {
        record.count += 1;
        if (record.count >= this.maxFailedAttempts) {
          Logger.warn('auth.rate_limit_exceeded', { agentId, count: record.count });
        }
      }
    }
  }

  // Verificar acceso a herramienta
  canAccess(token: AuthToken, tool: string): boolean {
    if (token.scope.includes('*')) return true;
    return token.scope.includes(tool);
  }

  // Verificar rol
  hasRole(token: AuthToken, role: string): boolean {
    return token.role === role || token.role === 'admin';
  }

  // Verificar múltiples roles
  hasAnyRole(token: AuthToken, roles: string[]): boolean {
    return roles.some((r) => this.hasRole(token, r));
  }

  // Refrescar token (emitir nuevo con mismo payload)
  refreshToken(token: AuthToken, _expiresIn?: string | number): string {
    const { agentId, scope, role } = token;
    return this.generateToken(agentId, scope, role);
  }

  // Limpiar tokens revocados expirados periódicamente (en producción, usar DB)
  cleanupRevoked(): void {
    // const now = Math.floor(Date.now() / 1000);
    let cleaned = 0;
    for (const _jti of this.revokedTokens) {
      // Simplificado: asumir que después de 24h ya expiró
      // En prod: almacenar exp con jti en DB y limpiar según exp
      cleaned++;
    }
    Logger.debug('auth.revoked_cleanup', { cleaned });
  }
}

