					<div className="pl-4 space-y-1">
						{agentFlow['orchestrator_core']?.map((agent) => (
							<div key={agent}>
								<span
									className={`cursor-pointer hover:text-cyan-300 ${selectedAgent === agent ? 'text-cyan-400 font-bold' : 'text-slate-400'}`}
