import LogsTimeline from './LogsTimeline';
import TaskQueue from './TaskQueue';
import AgentCard from './AgentCard';
import MCPsPanel from './tabs/MCPsPanel';
import PerformancePanel from './tabs/PerformancePanel';
import ConfigEditor from './tabs/ConfigEditor';
import DocsPanel from './tabs/DocsPanel';
import { useMetrics } from '../../hooks/useMetrics';
import { usePreferences } from '../../hooks/usePreferences';
import type { AgentStats } from '../../src/lib/metrics';

type TabType = 'dashboard' | 'mcps' | 'performance' | 'config' | 'docs';

export default function DashboardLayout() {
	const [activeTab, setActiveTab] = useState<TabType>('dashboard');
	const [selectedAgent, setSelectedAgent] = useState<string | null>(null);
	const [logFilter, setLogFilter] = useState({ agent: 'all', level: 'all' });
	const { agentStats } = useMetrics(2000);
	const { prefs, toggleDarkMode } = usePreferences();

	return (
		<div className={prefs.darkMode ? 'dark' : ''}>
			<div className="min-h-screen bg-slate-950 text-slate-50">
				{/* Header con Tabs */}
				<header className="bg-slate-900 border-b border-slate-700">
					<div className="px-6 py-4 flex justify-between items-center mb-4">
						<div className="flex items-center gap-3">
							<h1 className="text-2xl font-bold text-cyan-400">AURA MCP</h1>
							<nav className="text-sm text-slate-400">
								{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}
								{selectedAgent && ` > ${selectedAgent}`}
							</nav>
						</div>
						<button
							onClick={toggleDarkMode}
							className="px-3 py-1 bg-slate-700 hover:bg-slate-600 rounded text-sm transition-colors"
						>
							{prefs.darkMode ? '☀️' : '🌙'}
						</button>
					</div>

					{/* Tabs Navigation */}
					<div className="flex border-t border-slate-700 px-6">
						{(['dashboard', 'mcps', 'performance', 'config', 'docs'] as TabType[]).map((tab) => (
							<button
								key={tab}
								onClick={() => setActiveTab(tab)}
								className={`px-4 py-3 text-sm font-medium transition-colors ${
									activeTab === tab
										? 'border-b-2 border-cyan-400 text-cyan-400'
										: 'text-slate-400 hover:text-slate-300'
								}`}
							>
								{tab === 'dashboard' && '📊 Dashboard'}
								{tab === 'mcps' && '🔌 MCPs'}
								{tab === 'performance' && '⚡ Performance'}
								{tab === 'config' && '⚙️ Config'}
								{tab === 'docs' && '📚 Docs'}
							</button>
						))}
					</div>
				</header>

				{/* Main Content */}
				<main className="p-6">
					{activeTab === 'dashboard' && (
						<div className="space-y-6">
							{/* Top Row: Status + Orchestration */}
							<div className="grid grid-cols-4 gap-6">
								<div className="col-span-1">
									<CoreStatusPanel />
								</div>
								<div className="col-span-3">
									<AgentOrchestrationMap onAgentSelect={setSelectedAgent} selectedAgent={selectedAgent} />
								</div>
							</div>

							{/* Agent Cards Grid */}
							<div>
								<h2 className="text-lg font-bold text-cyan-400 mb-4">Active Agents</h2>
								<div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
									{agentStats.map((stats) => (
										<AgentCard
											key={stats.name}
											agentName={stats.name}
											stats={stats}
											onClick={() => setSelectedAgent(stats.name)}
											selected={selectedAgent === stats.name}
										/>
									))}
								</div>
							</div>

							{/* Task Queue + Recent Executions */}
							<div className="grid grid-cols-2 gap-6">
								<TaskQueue />
								<RecentExecutions selectedAgent={selectedAgent} />
							</div>

							{/* Logs Timeline */}
							<div>
								<LogsTimeline
									filter={logFilter}
									onFilterChange={setLogFilter}
									selectedAgent={selectedAgent}
								/>
							</div>
						</div>
					)}

					{activeTab === 'mcps' && <MCPsPanel />}
					{activeTab === 'performance' && <PerformancePanel selectedAgent={selectedAgent} />}
					{activeTab === 'config' && <ConfigEditor />}
					{activeTab === 'docs' && <DocsPanel />}
				</main>
			</div>
		</div>
	);
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';

import { metricsCollector } from '../../src/lib/metrics';
import type { ExecutionMetric } from '../../src/lib/metrics';

type Props = {
	filter: { agent: string; level: string };
	onFilterChange: (filter: { agent: string; level: string }) => void;
	selectedAgent: string | null;
};

export default function LogsTimeline({ filter, onFilterChange, selectedAgent }: Props) {
	const [logs, setLogs] = useState<ExecutionMetric[]>([]);
	const [allAgents, setAllAgents] = useState<string[]>([]);
	const [expandedLogId, setExpandedLogId] = useState<string | null>(null);
	const [searchText, setSearchText] = useState('');
	const [debouncedSearch, setDebouncedSearch] = useState('');

	// Debounce search 300ms
	useEffect(() => {
		const timer = setTimeout(() => setDebouncedSearch(searchText), 300);
		return () => clearTimeout(timer);
	}, [searchText]);

	useEffect(() => {
		const unsub = metricsCollector.onExecutionRecorded((metric) => {
			setLogs((prev) => [metric, ...prev].slice(0, 50));
			setAllAgents((prev) => {
				const set = new Set([...prev, metric.agentName]);
				return Array.from(set).sort();
			});
		});

		const allStats = metricsCollector.getAllAgentStats();
		setAllAgents(allStats.map((s) => s.name).sort());

		return () => unsub();
	}, []);

	// Aplicar filtros
	const filtered = useMemo(() => {
		return logs.filter((log) => {
			if (filter.agent !== 'all' && log.agentName !== filter.agent) return false;
			if (debouncedSearch && !log.agentName.toLowerCase().includes(debouncedSearch.toLowerCase()))
				return false;
			return true;
		});
	}, [logs, filter, debouncedSearch]);

	const exportLogs = useCallback((format: 'json' | 'csv') => {
		const dataToExport = filtered.map((log) => ({
			timestamp: new Date(log.timestamp).toISOString(),
			agent: log.agentName,
			latency: log.latencyMs,
			status: log.success ? 'success' : 'failed',
			cid: log.correlationId || 'n/a',
		}));

		if (format === 'json') {
			const json = JSON.stringify(dataToExport, null, 2);
			const blob = new Blob([json], { type: 'application/json' });
			const url = URL.createObjectURL(blob);
			const a = document.createElement('a');
			a.href = url;
			a.download = `logs-${Date.now()}.json`;
			a.click();
		} else if (format === 'csv') {
			const headers = ['Timestamp', 'Agent', 'Latency (ms)', 'Status', 'Correlation ID'];
			const rows = dataToExport.map((d) => [d.timestamp, d.agent, d.latency, d.status, d.cid]);
			const csv = [headers, ...rows].map((r) => r.join(',')).join('\n');
			const blob = new Blob([csv], { type: 'text/csv' });
			const url = URL.createObjectURL(blob);
			const a = document.createElement('a');
			a.href = url;
			a.download = `logs-${Date.now()}.csv`;
			a.click();
		}
	}, [filtered]);

	const formatTime = (ts: number): string => {
		const d = new Date(ts);
		return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}:${d.getSeconds().toString().padStart(2, '0')}`;
	};

	return (
		<div className="bg-slate-800 rounded-lg border border-slate-700 p-4">
			<div className="flex justify-between items-center mb-4">
				<h3 className="text-lg font-bold text-cyan-400">Logs Timeline (Live)</h3>

				<div className="flex gap-3">
					<input
						type="text"
						placeholder="Search agents... (debounce 300ms)"
						value={searchText}
						onChange={(e) => setSearchText(e.target.value)}
						className="bg-slate-700 border border-slate-600 text-slate-50 px-3 py-1 rounded text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500"
					/>

					<select
						value={filter.agent}
						onChange={(e) => onFilterChange({ ...filter, agent: e.target.value })}
						className="bg-slate-700 border border-slate-600 text-slate-50 px-3 py-1 rounded text-sm"
					>
						<option value="all">All Agents</option>
						{allAgents.map((agent) => (
							<option key={agent} value={agent}>
								{agent}
							</option>
						))}
					</select>

					<button
						onClick={() => exportLogs('json')}
						className="px-3 py-1 bg-cyan-600 hover:bg-cyan-700 rounded text-xs font-bold transition-colors"
					>
						📥 JSON
					</button>
					<button
						onClick={() => exportLogs('csv')}
						className="px-3 py-1 bg-cyan-600 hover:bg-cyan-700 rounded text-xs font-bold transition-colors"
					>
						📊 CSV
					</button>
				</div>
			</div>

			{/* Timeline con expandibles */}
			<div className="bg-slate-900 p-4 rounded font-mono text-sm max-h-96 overflow-y-auto space-y-2">
				{filtered.length > 0 ? (
					filtered.map((log, idx) => {
						const logId = `${log.timestamp}-${idx}`;
						const isExpanded = expandedLogId === logId;

						return (
							<div
								key={logId}
								className="border-l-2 border-slate-700 pl-3 py-1 cursor-pointer hover:bg-slate-800 transition-all group"
								onClick={() => setExpandedLogId(isExpanded ? null : logId)}
							>
								{/* Main row */}
								<div className="flex gap-3 text-slate-300">
									<span className="text-slate-500 w-12 flex-shrink-0">{formatTime(log.timestamp)}</span>
									<span
										className={`font-bold w-4 flex-shrink-0 ${log.success ? 'text-green-400' : 'text-red-400'}`}
									>
										{log.success ? '✓' : '✕'}
									</span>
									<span className="text-cyan-400 flex-shrink-0">[{log.agentName}]</span>
									<span className="text-slate-400 flex-1">
										{log.success ? 'OK' : 'ERROR'} ({log.latencyMs}ms)
									</span>
									<span className="text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity">
										{isExpanded ? '▼' : '▶'}
									</span>
								</div>

								{/* Expanded */}
								{isExpanded && (
									<div className="mt-2 pt-2 border-t border-slate-700 pl-3 space-y-1 text-xs text-slate-300 animate-slideDown">
										<div>
											<span className="text-slate-500">Full ID:</span> {log.correlationId || 'n/a'}
										</div>
										<div>
											<span className="text-slate-500">Latency:</span> {log.latencyMs}ms
										</div>
										{log.errorMessage && (
											<div className="text-red-400">
												<span className="text-slate-500">Error:</span> {log.errorMessage}
											</div>
										)}
										{log.tokensUsed && (
											<div>
												<span className="text-slate-500">Tokens:</span> {log.tokensUsed}
											</div>
										)}
									</div>
								)}
							</div>
						);
					})
				) : (
					<div className="text-center text-slate-500 py-8">No logs matching filter</div>
				)}
			</div>
		</div>
	);
}

import React, { useState, useEffect } from 'react';
import chalk from 'chalk';
import { Logger } from '../../services/logger';

interface McpFile {
	id: string;
	name: string;
	path: string;
	metadata: {
		title: string;
		description: string;
		importedFrom: string;
		importDate: string;
		wordCount: number;
		lineCount: number;
	};
	status: 'raw_import' | 'refined' | 'validated' | 'published';
	createdAt: string;
}

export default function McpImportedTab() {
	const [mcps, setMcps] = useState<McpFile[]>([]);
	const [selectedMcp, setSelectedMcp] = useState<McpFile | null>(null);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);

	useEffect(() => {
		fetchMcps();
	}, []);

	const fetchMcps = async () => {
		setLoading(true);
		try {
			const res = await fetch('/api/mcp');
			const data = await res.json();
			setMcps(data.mcps || []);
			setError(null);
		} catch (err) {
			setError((err as Error).message);
			Logger.error('dashboard.mcpImported.fetchError', { error: (err as Error).message });
		} finally {
			setLoading(false);
		}
	};

	const handleDelete = async (id: string) => {
		if (!confirm(`¿Eliminar MCP: ${id}?`)) return;

		try {
			const res = await fetch(`/api/mcp/${id}`, { method: 'DELETE' });
			if (res.ok) {
				setMcps((prev) => prev.filter((m) => m.id !== id));
				setSelectedMcp(null);
				Logger.info('dashboard.mcpImported.deleted', { id });
			}
		} catch (err) {
			Logger.error('dashboard.mcpImported.deleteError', { error: (err as Error).message });
		}
	};

	const getStatusColor = (status: string): string => {
		switch (status) {
			case 'raw_import':
				return 'bg-yellow-900 text-yellow-400';
			case 'refined':
				return 'bg-blue-900 text-blue-400';
			case 'validated':
				return 'bg-green-900 text-green-400';
			case 'published':
				return 'bg-purple-900 text-purple-400';
			default:
				return 'bg-gray-900 text-gray-400';
		}
	};

	return (
		<div className="space-y-6 p-6">
			<div className="flex justify-between items-center">
				<h2 className="text-2xl font-bold text-cyan-400">📦 MCPs Importados</h2>
				<button
					onClick={fetchMcps}
					disabled={loading}
					className="px-4 py-2 bg-cyan-600 hover:bg-cyan-700 disabled:opacity-50 rounded font-medium"
				>
					{loading ? '⏳ Cargando...' : '🔄 Actualizar'}
				</button>
			</div>

			{error && <div className="bg-red-900 text-red-400 p-4 rounded">{error}</div>}

			{mcps.length === 0 ? (
				<div className="text-center py-12 bg-slate-800 rounded-lg border-2 border-dashed border-slate-600">
					<p className="text-slate-400">📭 No hay MCPs importados</p>
					<p className="text-sm text-slate-500 mt-2">
						Usa <code className="bg-slate-900 px-2 py-1 rounded">aura ingest documento.pdf</code> para importar
					</p>
				</div>
			) : (
				<div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
					{/* Lista de MCPs */}
					<div className="lg:col-span-1 space-y-2">
						<div className="bg-slate-800 rounded-lg border border-slate-700 overflow-hidden">
							{mcps.map((mcp) => (
								<button
									key={mcp.id}
									onClick={() => setSelectedMcp(mcp)}
									className={`w-full text-left px-4 py-3 border-b border-slate-700 hover:bg-slate-700 transition-colors ${
										selectedMcp?.id === mcp.id ? 'bg-cyan-500/20 border-l-4 border-l-cyan-400' : ''
									}`}
								>
									<div className="flex items-center justify-between">
										<div className="flex-1 min-w-0">
											<p className="font-bold text-cyan-400 truncate">{mcp.metadata.title}</p>
											<p className="text-xs text-slate-400 truncate">{mcp.name}</p>
										</div>
										<span className={`px-2 py-1 rounded text-xs font-bold ml-2 whitespace-nowrap ${getStatusColor(mcp.status)}`}>
											{mcp.status}
										</span>
									</div>
								</button>
							))}
						</div>
						<p className="text-xs text-slate-500 text-center">Total: {mcps.length}</p>
					</div>

					{/* Detalle del MCP seleccionado */}
					{selectedMcp && (
						<div className="lg:col-span-2 space-y-4">
							<div className="bg-slate-800 rounded-lg border border-slate-700 p-6">
								<div className="flex justify-between items-start mb-4">
									<div>
										<h3 className="text-2xl font-bold text-cyan-400">{selectedMcp.metadata.title}</h3>
										<p className="text-slate-400 mt-2">{selectedMcp.metadata.description}</p>
									</div>
									<button
										onClick={() => handleDelete(selectedMcp.id)}
										className="px-3 py-2 bg-red-600 hover:bg-red-700 rounded text-sm font-bold"
									>
										🗑️ Eliminar
									</button>
								</div>

								<div className="grid grid-cols-2 gap-4 mb-6">
									<div className="bg-slate-700 p-3 rounded">
										<div className="text-slate-400 text-xs">Importado desde</div>
										<div className="text-yellow-400 font-mono text-sm">{selectedMcp.metadata.importedFrom}</div>
									</div>
									<div className="bg-slate-700 p-3 rounded">
										<div className="text-slate-400 text-xs">Fecha de importación</div>
										<div className="text-blue-400 font-mono text-sm">
											{new Date(selectedMcp.metadata.importDate).toLocaleString()}
										</div>
									</div>
									<div className="bg-slate-700 p-3 rounded">
										<div className="text-slate-400 text-xs">Palabras</div>
										<div className="text-green-400 font-bold">{selectedMcp.metadata.wordCount}</div>
									</div>
									<div className="bg-slate-700 p-3 rounded">
										<div className="text-slate-400 text-xs">Líneas</div>
										<div className="text-green-400 font-bold">{selectedMcp.metadata.lineCount}</div>
									</div>
								</div>

								{/* Acciones */}
								<div className="space-y-2">
									<button className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded font-medium">
										🔍 Ver contenido
									</button>
									<button className="w-full px-4 py-2 bg-purple-600 hover:bg-purple-700 rounded font-medium">
										🔄 Refinar automáticamente
									</button>
									<button className="w-full px-4 py-2 bg-green-600 hover:bg-green-700 rounded font-medium">
										✅ Validar
									</button>
									<button className="w-full px-4 py-2 bg-orange-600 hover:bg-orange-700 rounded font-medium">
										📤 Exportar
									</button>
								</div>

								{/* Status detail */}
								<div className="mt-6 pt-6 border-t border-slate-600">
									<h4 className="text-sm font-bold text-slate-400 mb-3">Estado Actual</h4>
									<div className={`px-4 py-3 rounded ${getStatusColor(selectedMcp.status)}`}>
										<p className="font-bold">
											{selectedMcp.status === 'raw_import' && '📥 Importación Bruta'}
											{selectedMcp.status === 'refined' && '✨ Refinado'}
											{selectedMcp.status === 'validated' && '✅ Validado'}
											{selectedMcp.status === 'published' && '🚀 Publicado'}
										</p>
										<p className="text-sm mt-2">
											{selectedMcp.status === 'raw_import' && 'Próximo paso: Refinar o Validar'}
											{selectedMcp.status === 'refined' && 'Próximo paso: Validar'}
											{selectedMcp.status === 'validated' && 'Próximo paso: Publicar o Exportar'}
											{selectedMcp.status === 'published' && 'Documento listo para usar'}
										</p>
									</div>
								</div>
							</div>
						</div>
					)}
				</div>
			)}
		</div>
	);
}

import React, { useMemo, useState, useEffect } from 'react';

import { metricsCollector } from '../../../../../src/lib/metrics';

type Props = {
	selectedAgent: string | null;
};

export default function PerformancePanel({ selectedAgent }: Props) {
	const allStats = metricsCollector.getAllAgentStats();

	// Simular datos históricos (en prod, desde base de datos)
	const [latencyTrend, setLatencyTrend] = useState<any[]>([]);

	useEffect(() => {
		const data = [];
		const baseTime = Date.now();
		for (let i = 0; i < 20; i++) {
			data.push({
				time: new Date(baseTime - (20 - i) * 10000).toLocaleTimeString(),
				latency: Math.random() * 200 + 50,
				errorRate: Math.random() * 0.1,
			});
		}
		setLatencyTrend(data);
	}, []);

	// Heatmap: agentes x herramientas
	const heatmapData = useMemo(() => {
		const tools = [
			'code.analyze',
			'code.refactor',
			'backtest.run',
			'data.query',
			'data.transform',
			'viz.generate',
		];
		return allStats.map((agent) => ({
			agent: agent.name,
			metrics: tools.map((tool) => ({
				tool,
				avgLatency: Math.random() * 300 + 50,
				successRate: Math.random() * 0.95 + 0.05,
			})),
		}));
	}, [allStats]);

	return (
		<div className="space-y-6">
			{/* Latency Trend */}
			<div className="bg-slate-800 rounded-lg border border-slate-700 p-4">
				<h3 className="text-lg font-bold text-cyan-400 mb-4">Latency Trend (Last 20 min)</h3>

				{/* Simple ASCII Chart */}
				<div className="bg-slate-900 p-4 rounded font-mono text-xs text-slate-300 overflow-x-auto">
					<div className="whitespace-pre">
						{`
    Latency (ms)
    │
 300│     ╱╲        ╱╲
    │    ╱  ╲      ╱  ╲
 200│   ╱    ╲    ╱    ╲
    │  ╱      ╲  ╱      ╲
 100│ ╱        ╲╱        ╲
    │╱                    ╲
   0└────────────────────────→ Time
    10:00  10:05  10:10  10:15
        `}
					</div>
				</div>

				{/* Stats */}
				<div className="mt-4 grid grid-cols-4 gap-4">
					<div className="bg-slate-700 p-3 rounded">
						<div className="text-slate-400 text-xs">Min Latency</div>
						<div className="text-yellow-400 font-bold">45ms</div>
					</div>
					<div className="bg-slate-700 p-3 rounded">
						<div className="text-slate-400 text-xs">Max Latency</div>
						<div className="text-orange-400 font-bold">287ms</div>
					</div>
					<div className="bg-slate-700 p-3 rounded">
						<div className="text-slate-400 text-xs">Avg Latency</div>
						<div className="text-blue-400 font-bold">125ms</div>
					</div>
					<div className="bg-slate-700 p-3 rounded">
						<div className="text-slate-400 text-xs">p99 Latency</div>
						<div className="text-red-400 font-bold">267ms</div>
					</div>
				</div>
			</div>

			{/* Performance Heatmap */}
			<div className="bg-slate-800 rounded-lg border border-slate-700 p-4">
				<h3 className="text-lg font-bold text-cyan-400 mb-4">Agent × Tool Performance Heatmap</h3>

				<div className="overflow-x-auto">
					<table className="w-full text-xs">
						<thead className="border-b border-slate-700 text-slate-400">
							<tr>
								<th className="text-left py-2 px-2">Agent / Tool</th>
								{heatmapData[0]?.metrics.slice(0, 3).map((m) => (
									<th key={m.tool} className="text-center py-2 px-2">
										{m.tool.split('.')[1]}
									</th>
								))}
							</tr>
						</thead>
						<tbody>
							{heatmapData.slice(0, 4).map((agent) => (
								<tr key={agent.agent} className="border-b border-slate-700">
									<td className="py-2 px-2 text-cyan-400">{agent.agent}</td>
									{agent.metrics.slice(0, 3).map((m: { tool: string; avgLatency: number; successRate: number }, idx) => {
										const intensity = m.avgLatency / 300;
										const bgColor =
											intensity < 0.33
												? 'bg-green-900'
												: intensity < 0.66
													? 'bg-yellow-900'
													: 'bg-red-900';
										return (
											<td key={idx} className={`py-2 px-2 text-center ${bgColor} text-slate-200`}>
												{Math.round(m.avgLatency)}ms
											</td>
										);
									})}
								</tr>
							))}
						</tbody>
					</table>
				</div>

				<div className="mt-4 text-xs text-slate-400">
					Green: &lt; 100ms | Yellow: 100-200ms | Red: &gt; 200ms
				</div>
			</div>

			{/* Top Slowest Agents */}
			<div className="bg-slate-800 rounded-lg border border-slate-700 p-4">
				<h3 className="text-lg font-bold text-cyan-400 mb-4">Top Slowest Agents</h3>

				<div className="space-y-2">
					{allStats
						.sort((a, b) => b.p99Latency - a.p99Latency)
						.slice(0, 5)
						.map((agent, idx) => (
							<div key={agent.name} className="flex justify-between items-center bg-slate-700 p-2 rounded">
								<div className="flex items-center gap-2">
									<span className="text-slate-400 text-xs">{idx + 1}.</span>
									<span className="text-cyan-400">{agent.name}</span>
								</div>
								<div className="flex gap-4">
									<span className="text-orange-400">p99: {Math.round(agent.p99Latency)}ms</span>
									<span className="text-yellow-400">avg: {Math.round(agent.averageLatency)}ms</span>
								</div>
							</div>
						))}
				</div>
			</div>
		</div>
	);
}

import React, { useEffect, useState, useMemo, useRef } from 'react';
import { McpCoreClient, LogEntry } from '../../services/mcpCoreClient';
import LogsPanel from '../ui/LogsPanel';

type Props = {
  client?: McpCoreClient;
  coreUrl?: string;
  maxEntries?: number;
};

export default function LogsContainer({ client, coreUrl, maxEntries = 200 }: Props) {
  const [logs, setLogs] = useState<LogEntry[]>([]);

  const { clientInstance, owns } = useMemo(() => {
    if (client) return { clientInstance: client, owns: false };
    try {
      const inst = (McpCoreClient as any).getInstance
        ? (McpCoreClient as any).getInstance(coreUrl)
        : null;
      if (inst) return { clientInstance: inst as McpCoreClient, owns: false };
    } catch {
      // Ignore errors
    }
    const created = new McpCoreClient(
      coreUrl ??
      (typeof window !== 'undefined' ? (window as any).__CORE_URL__ : 'http://localhost:3000')
    );
    return { clientInstance: created, owns: true };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [client, coreUrl]);

  // buffer para batching
  const bufferRef = useRef<LogEntry[]>([]);
  const rafRef = useRef<number | null>(null);

  const flushBuffer = () => {
    const buf = bufferRef.current;
    if (buf.length === 0) return;
    setLogs((prev) => {
      const merged = [...prev, ...buf].slice(-maxEntries);
      return merged;
    });
    bufferRef.current = [];
    rafRef.current = null;
  };

  useEffect(() => {
    let mounted = true;

    const pushLogBuffered = (entry: LogEntry) => {
      bufferRef.current.push(entry);
      // schedule flush via rAF if not scheduled
      if (rafRef.current == null) {
        rafRef.current = (window as any).requestAnimationFrame
          ? (window as any).requestAnimationFrame(() => flushBuffer())
          : (window.setTimeout(() => flushBuffer(), 50) as unknown as number);
      }
    };

    (async () => {
      try {
        const initial = await clientInstance.getLogs();
        if (!mounted) return;
        if (Array.isArray(initial) && initial.length) {
          setLogs((prev) => [...prev, ...initial].slice(-maxEntries));
        }
      } catch (err: any) {
        // error ignored
      } finally {
        // cleanup
      }
    })();

    const unsub = clientInstance.subscribe('logs', (l: LogEntry) => {
      if (!mounted) return;
      pushLogBuffered(l);
    });

    return () => {
      mounted = false;
      unsub();
      // flush remaining buffer
      if (rafRef.current != null) {
        try {
          (window as any).cancelAnimationFrame?.(rafRef.current);
        } catch {
          // Ignore
        }
        flushBuffer();
      }
      if (owns) {
        try {
          clientInstance.disconnect();
        } catch {
          // Ignore
        }
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clientInstance, maxEntries, owns]);

  return <LogsPanel logs={logs} />;
}

import { useState, useEffect, useCallback } from 'react';

export type Preferences = {
	darkMode: boolean;
	visibleColumns: string[];
	autoRefresh: boolean;
	expandedAgents: string[];
};

const STORAGE_KEY = 'aura-dashboard-prefs';

const DEFAULT_PREFS: Preferences = {
	darkMode: true,
	visibleColumns: ['executions', 'latency', 'successRate'],
	autoRefresh: true,
	expandedAgents: [],
};

export function usePreferences() {
	const [prefs, setPrefs] = useState<Preferences>(() => {
		try {
			const stored = localStorage.getItem(STORAGE_KEY);
			return stored ? { ...DEFAULT_PREFS, ...JSON.parse(stored) } : DEFAULT_PREFS;
		} catch {
			return DEFAULT_PREFS;
		}
	});

	const updatePrefs = useCallback((updater: Partial<Preferences> | ((p: Preferences) => Preferences)) => {
		setPrefs((prev) => {
			const next = typeof updater === 'function' ? updater(prev) : { ...prev, ...updater };
			try {
				localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
			} catch {
				console.warn('Failed to save preferences');
			}
			return next;
		});
	}, []);

	const toggleDarkMode = useCallback(() => {
		updatePrefs((p) => ({ ...p, darkMode: !p.darkMode }));
	}, [updatePrefs]);

	const toggleColumnVisibility = useCallback((col: string) => {
		updatePrefs((p) => ({
			...p,
			visibleColumns: p.visibleColumns.includes(col)
				? p.visibleColumns.filter((c) => c !== col)
				: [...p.visibleColumns, col],
		}));
	}, [updatePrefs]);

	const toggleAgentExpanded = useCallback((agentName: string) => {
		updatePrefs((p) => ({
			...p,
			expandedAgents: p.expandedAgents.includes(agentName)
				? p.expandedAgents.filter((a) => a !== agentName)
				: [...p.expandedAgents, agentName],
		}));
	}, [updatePrefs]);

	return {
		prefs,
		updatePrefs,
		toggleDarkMode,
		toggleColumnVisibility,
		toggleAgentExpanded,
	};
}
